-- Compiler correctness.
-- A compiler from arithmetic expressions (numbers and +) to instructions for a
-- stack machine, with a proof that running the compiled code leaves the
-- expression's value on the stack. This small setting is known as "Hutton's
-- razor".
--
-- Two guarantees are carried by types:
--   * Code(i, j) is code that takes a stack of i numbers to a stack of j. Code
--     that would pop from an empty stack has no type, so it cannot be written.
--   * compile returns its code together with evidence that running it pushes
--     the value of the expression.
--
-- If Pledge is new to you:
--   * `data` declares a type and lists every way to build a value of it.
--   * A type can take values as parameters. `Plus(m, n, r)` below is a separate
--     type for each three numbers, and it is written so that a value of it can
--     be built only when m + n = r. So a value of type `Plus(m, n, r)` is
--     evidence, a proof, that m + n = r. Most types in this file are like that.
--   * `erased` marks what exists only for the checker. Running the program
--     skips it, so here the proofs cost nothing at run time.
--   * The Tutorial link at the top of the page teaches all of this in order.

-- Numbers, built by hand: Zero(), then Succ(Zero()) for 1, and so on.
-- Everything applied is written with parentheses, even with no arguments.
data Nat() : Type() {
  Zero() : Nat();
  Succ(pred : Nat()) : Nat();
}

-- Plus(m, n, r) reads "m + n = r". Its two lines are the rules that define
-- addition: zero plus n is n, and (m + 1) + n = r + 1 whenever m + n = r.
--
-- Addition is written as a type because a Pledge type cannot contain a function
-- call. Eval below can mention Plus(m, n, r); it could not mention plus(m, n).
data Plus(m : Nat(), n : Nat(), r : Nat()) : Type() {
  PlusZero(erased n : Nat()) : Plus(Zero(), n, n);
  PlusSucc(erased m : Nat(), erased n : Nat(), erased r : Nat(),
      p : Plus(m, n, r)) : Plus(Succ(m), n, Succ(r));
}

-- The function that does the adding. Its second result ties it to the type
-- above: evidence that what it returns is the sum.
--
-- `subterm` is how a recursive function shows that it ends: each recursive call
-- must pass, for that parameter, a piece of the caller's own argument. Here
-- that is k, the inside of m = Succ(k). The checker demands this of every
-- recursive function; one that might loop forever is rejected.
--
-- `match m : _` : after the colon comes what the match produces, and `_` leaves
-- it to the checker, which knows it from the return type. As an argument, `_`
-- is an erased value the checker can work out for itself.
fn plus(subterm m : Nat(), n : Nat()) -> (r : Nat(), erased p : Plus(m, n, r)) {
  match m : _ {
    Zero() => (n, PlusZero(_));
    Succ(k) => {
      let (r, erased p) = plus(subterm k, n);
      (Succ(r), PlusSucc(_, _, _, p))
    };
  }
}

-- The source language: a number, or the sum of two expressions.
data Expr() : Type() {
  Lit(n : Nat()) : Expr();
  Add(a : Expr(), b : Expr()) : Expr();
}

-- Eval(e, n) reads "expression e has the value n". This is the definition of
-- what expressions mean, and it is what the compiler is judged against.
data Eval(e : Expr(), n : Nat()) : Type() {
  EvalLit(erased n : Nat()) : Eval(Lit(n), n);
  EvalAdd(erased a : Expr(), erased b : Expr(), erased m : Nat(),
      erased n : Nat(), erased r : Nat(), pa : Eval(a, m), pb : Eval(b, n),
      p : Plus(m, n, r)) : Eval(Add(a, b), r);
}

-- An interpreter. It returns the value with evidence that this is the value
-- Eval gives the expression.
fn eval(subterm e : Expr()) -> (n : Nat(), erased p : Eval(e, n)) {
  match e : _ {
    Lit(n) => (n, EvalLit(_));
    Add(a, b) => {
      let (m, erased pa) = eval(subterm a);
      let (n, erased pb) = eval(subterm b);
      let (r, erased p) = plus(m, n);
      (r, EvalAdd(_, _, _, _, _, pa, pb, p))
    };
  }
}

-- The machine's stack. Stack(d) is a stack of exactly d numbers, so the type
-- says how much there is to pop.
data Stack(d : Nat()) : Type() {
  SNil() : Stack(Zero());
  SCons(erased d : Nat(), x : Nat(), rest : Stack(d)) : Stack(Succ(d));
}

-- Machine code. Each instruction holds the code that runs after it. Code(i, j)
-- reads "started on a stack of i numbers, this ends on a stack of j":
--   * HALT stops and leaves the stack as it is.
--   * PUSH puts n on the stack, so the code after it starts one deeper.
--   * ADD replaces the top two numbers by their sum. Its type starts at
--     Succ(Succ(d)), a stack of at least two.
data Code(i : Nat(), j : Nat()) : Type() {
  HALT(erased d : Nat()) : Code(d, d);
  PUSH(erased d : Nat(), erased j : Nat(), n : Nat(), c : Code(Succ(d), j))
    : Code(d, j);
  ADD(erased d : Nat(), erased j : Nat(), c : Code(Succ(d), j))
    : Code(Succ(Succ(d)), j);
}

-- Exec(i, j, c, s, t) reads "running code c on stack s ends with stack t".
-- There is one rule per instruction, and together they define what the machine
-- does. In ExecAdd the stack starts with n on top of m, and the rest of the
-- code runs with their sum r in their place.
data Exec(i : Nat(), j : Nat(), c : Code(i, j), s : Stack(i),
    t : Stack(j)) : Type() {
  ExecHalt(erased d : Nat(), erased s : Stack(d)) : Exec(d, d, HALT(d), s, s);
  ExecPush(erased d : Nat(), erased j : Nat(), erased n : Nat(),
      erased c : Code(Succ(d), j), erased s : Stack(d), erased t : Stack(j),
      x : Exec(Succ(d), j, c, SCons(d, n, s), t))
    : Exec(d, j, PUSH(d, j, n, c), s, t);
  ExecAdd(erased d : Nat(), erased j : Nat(), erased c : Code(Succ(d), j),
      erased m : Nat(), erased n : Nat(), erased r : Nat(), erased s : Stack(d),
      erased t : Stack(j), p : Plus(m, n, r),
      x : Exec(Succ(d), j, c, SCons(d, r, s), t))
    : Exec(Succ(Succ(d)), j, ADD(d, j, c), SCons(Succ(d), n, SCons(d, m, s)),
        t);
}

-- The machine. It returns the final stack with evidence that this is the stack
-- Exec describes.
fn exec(erased i : Nat(), erased j : Nat(), subterm c : Code(i, j),
    s : Stack(i))
    -> (t : Stack(j), erased x : Exec(i, j, c, s, t)) {
  match c : _ {
    HALT(_) => (s, ExecHalt(_, _));
    PUSH(_, _, n, c1) => {
      let (t, erased x) = exec(_, _, subterm c1, SCons(_, n, s));
      (t, ExecPush(_, _, _, _, _, _, x))
    };
    ADD(_, _, c1) => {
      -- A `let` with a constructor on the left takes a value apart. It is
      -- accepted only when the value can have been built no other way. So no
      -- test for an empty stack is needed: in this branch s has type
      -- Stack(Succ(Succ(d))), and SNil() only builds a Stack(Zero()).
      let SCons(_, n, s1) = s;
      let SCons(_, m, s2) = s1;
      let (r, erased p) = plus(m, n);
      let (t, erased x) = exec(_, _, subterm c1, SCons(_, r, s2));
      (t, ExecAdd(_, _, _, _, _, _, _, _, p, x))
    };
  }
}

-- The compiler. It is given the code c that should run afterwards, and returns
-- code that works out e, pushes its value and carries on with c. Only e and c
-- exist at run time.
--
-- The erased parameters and result state what "correct" means. Suppose e has
-- the value n (pe), and c, run on stack s with n pushed, ends with stack t (x).
-- Then the returned code k, run on s, ends with t as well (y).
fn compile(subterm e : Expr(), erased n : Nat(), erased pe : Eval(e, n),
    erased d : Nat(), erased j : Nat(), c : Code(Succ(d), j),
    erased s : Stack(d), erased t : Stack(j),
    erased x : Exec(Succ(d), j, c, SCons(d, n, s), t))
    -> (k : Code(d, j), erased y : Exec(d, j, k, s, t)) {
  match e : _ {
    -- Matching on evidence tells the checker what the evidence says. pe has
    -- type Eval(Lit(v), n), and the only rule for a Lit, EvalLit, gives Lit(v)
    -- the value v. So inside the branch the checker knows that n is v, which is
    -- what makes "PUSH v" the right code.
    Lit(v) => match erased pe : _ {
      EvalLit(_) => (PUSH(_, _, v, c), ExecPush(_, _, _, _, _, _, x));
    };
    -- Built from the back. The code for b is told to carry on with ADD and then
    -- c; the code for a is told to carry on with the code for b. So at run time
    -- a's value is pushed, then b's, then the two are added.
    Add(a, b) => {
      let erased EvalAdd(_, _, m, n2, _, pa, pb, p) = pe;
      let (kb, erased yb) = compile(subterm b, _, pb, _, _, ADD(_, _, c),
          SCons(_, m, s), _, ExecAdd(_, _, _, _, _, _, _, _, p, x));
      compile(subterm a, _, pa, _, _, kb, _, _, yb)
    };
  }
}

-- A whole program: compile e, then stop.
fn compileTop(e : Expr(), erased n : Nat(), erased pe : Eval(e, n),
    erased d : Nat(), erased s : Stack(d))
    -> (k : Code(d, Succ(d)),
        erased y : Exec(d, Succ(d), k, s, SCons(d, n, s))) {
  compile(e, _, pe, _, _, HALT(_), _, _, ExecHalt(_, _))
}

-- `goal` states the theorem, here as the signature a function must have: for
-- every expression e with value n and every stack s, it returns code k, and
-- evidence that k run on s ends with n pushed on top of s. `qed compileTop` has
-- the checker confirm that compileTop is such a function. The page reports
-- whether the goal is proved.
goal fn (e : Expr(), erased n : Nat(), erased pe : Eval(e, n), erased d : Nat(),
    erased s : Stack(d))
    -> (k : Code(d, Succ(d)),
        erased y : Exec(d, Succ(d), k, s, SCons(d, n, s)));
qed compileTop;

-- Code at the top level runs as soon as it is checked. This is 2 + (1 + 3).
-- `print` shows a value next to the statement: the value 6, then the compiled
-- code, then the stack after running that code on an empty stack. Erased fields
-- are not there at run time and print as `_`.
let e = Add(Lit(Succ(Succ(Zero()))),
    Add(Lit(Succ(Zero())), Lit(Succ(Succ(Succ(Zero()))))));
let (n, erased pe) = eval(e);
print n;
let (k, erased y) = compileTop(e, _, pe, _, SNil());
print k;
let (t, erased x) = exec(_, _, k, SNil());
print t;

-- Insertion sort.
-- An ordinary insertion sort on lists of numbers. What is unusual is its type,
-- which says what sorting means: the result is in ascending order and is a
-- rearrangement of the input. The checker accepts `sort` only because its body
-- builds evidence of both.
--
-- If Pledge is new to you:
--   * `data` declares a type and lists every way to build a value of it.
--   * A type can take values as parameters. `Le(m, n)` below is a separate type
--     for each pair of numbers, and it is written so that a value of it can be
--     built only when m <= n. So a value of type `Le(m, n)` is evidence, a
--     proof, that m <= n. Most types in this file are like that.
--   * `erased` marks what exists only for the checker. Running the program
--     skips it, so here the proofs cost nothing at run time.
--   * The Tutorial link at the top of the page teaches all of this in order.

-- Numbers, built by hand: Zero(), then Succ(Zero()) for 1, and so on.
-- Everything applied is written with parentheses, even with no arguments.
data Nat() : Type() {
  Zero() : Nat();
  Succ(pred : Nat()) : Nat();
}

-- Le(m, n) reads "m <= n". Its two lines are the two rules that make it true:
-- zero is <= every n, and m + 1 <= n + 1 whenever m <= n. There is no way to
-- build evidence that 2 <= 1.
data Le(m : Nat(), n : Nat()) : Type() {
  LeZero(erased n : Nat()) : Le(Zero(), n);
  LeSucc(erased m : Nat(), erased n : Nat(), p : Le(m, n))
    : Le(Succ(m), Succ(n));
}

-- The answer to "is m <= n or the other way round?", with evidence for
-- whichever it is. A plain boolean would say which branch was taken but leave
-- the checker knowing nothing more about m and n.
data Order(m : Nat(), n : Nat()) : Type() {
  LeOrd(erased m : Nat(), erased n : Nat(), erased p : Le(m, n)) : Order(m, n);
  GeOrd(erased m : Nat(), erased n : Nat(), erased p : Le(n, m)) : Order(m, n);
}

-- `subterm` is how a recursive function shows that it ends: each recursive call
-- must pass, for that parameter, a piece of the caller's own argument. Here
-- that is m1, the inside of m = Succ(m1). The checker demands this of every
-- recursive function; one that might loop forever is rejected.
--
-- `match m : _` : after the colon comes what the match produces, and `_` leaves
-- it to the checker, which knows it from the return type. As an argument, `_`
-- is an erased value the checker can work out for itself.
fn compare(subterm m : Nat(), n : Nat()) -> (o : Order(m, n)) {
  match m : _ {
    Zero() => LeOrd(_, _, LeZero(_));
    Succ(m1) => match n : _ {
      Zero() => GeOrd(_, _, LeZero(_));
      Succ(n1) => match compare(subterm m1, n1) : _ {
        LeOrd(_, _, p) => LeOrd(_, _, LeSucc(_, _, p));
        GeOrd(_, _, p) => GeOrd(_, _, LeSucc(_, _, p));
      };
    };
  }
}

data List() : Type() {
  Nil() : List();
  Cons(head : Nat(), tail : List()) : List();
}

-- Below(x, xs) reads "x <= the first element of xs, if xs has one".
data Below(x : Nat(), xs : List()) : Type() {
  BelowNil(erased x : Nat()) : Below(x, Nil());
  BelowCons(erased x : Nat(), erased y : Nat(), erased ys : List(),
      p : Le(x, y)) : Below(x, Cons(y, ys));
}

-- Sorted(xs) reads "xs is in ascending order": every element is Below the part
-- of the list that follows it.
data Sorted(xs : List()) : Type() {
  SortedNil() : Sorted(Nil());
  SortedCons(erased x : Nat(), erased xs : List(), b : Below(x, xs),
      s : Sorted(xs)) : Sorted(Cons(x, xs));
}

-- Insert(x, xs, ys) reads "ys is xs with x put in somewhere": at the front
-- (InsHere), or further in, past the first element y (InsThere).
data Insert(x : Nat(), xs : List(), ys : List()) : Type() {
  InsHere(erased x : Nat(), erased xs : List()) : Insert(x, xs, Cons(x, xs));
  InsThere(erased x : Nat(), erased y : Nat(), erased xs : List(),
      erased ys : List(), i : Insert(x, xs, ys))
    : Insert(x, Cons(y, xs), Cons(y, ys));
}

-- Perm(xs, ys) reads "ys is a rearrangement of xs": rearrange all of xs but its
-- first element, then put that element in somewhere.
data Perm(xs : List(), ys : List()) : Type() {
  PermNil() : Perm(Nil(), Nil());
  PermCons(erased x : Nat(), erased xs : List(), erased ys : List(),
      erased zs : List(), p : Perm(xs, ys), i : Insert(x, ys, zs))
    : Perm(Cons(x, xs), zs);
}

-- A helper fact for insert: if y <= x and y is Below xs, then y is still Below
-- the list once x has been inserted into it.
fn belowInsert(erased y : Nat(), erased x : Nat(), erased xs : List(),
    erased ys : List(), p : Le(y, x), b : Below(y, xs), i : Insert(x, xs, ys))
    -> (c : Below(y, ys)) {
  match i : _ {
    InsHere(_, _) => BelowCons(_, _, _, p);
    InsThere(_, _, _, _, _) => {
      -- A `let` with a constructor on the left takes a value apart. It is
      -- accepted only when the value can have been built no other way. Here the
      -- list is a Cons, and BelowNil only ever talks about Nil(), so b must be
      -- a BelowCons.
      let BelowCons(_, _, _, q) = b;
      BelowCons(_, _, _, q)
    };
  }
}

-- Puts x into a sorted list. A function can return several values: here the new
-- list ys, then two erased ones, evidence that ys is xs with x inserted and
-- evidence that ys is sorted. The third parameter demands evidence that the
-- input was sorted, so insert cannot be called on an unsorted list.
fn insert(x : Nat(), subterm xs : List(), erased s : Sorted(xs))
    -> (ys : List(), erased i : Insert(x, xs, ys), erased t : Sorted(ys)) {
  match xs : _ {
    Nil() => (Cons(x, Nil()), InsHere(_, _),
        SortedCons(_, _, BelowNil(_), SortedNil()));
    -- The branch taken depends on a value that exists at run time, so compare's
    -- result is not erased. The p inside it is: it only feeds the proofs.
    Cons(y, rest) => match compare(x, y) : _ {
      LeOrd(_, _, p) => (Cons(x, xs), InsHere(_, _),
          SortedCons(_, _, BelowCons(_, _, rest, p), s));
      GeOrd(_, _, p) => {
        -- s is erased, so what comes out of it is erased too: `let erased`.
        let erased SortedCons(_, _, b, s1) = s;
        let (zs, erased j, erased t1) = insert(x, subterm rest, s1);
        (Cons(y, zs), InsThere(_, _, _, _, j),
            SortedCons(_, _, belowInsert(_, _, _, _, p, b, j), t1))
      };
    };
  }
}

-- The algorithm itself: sort the rest, then insert the first element. The
-- second and third results put the evidence together the same way.
fn sort(subterm xs : List())
    -> (ys : List(), erased p : Perm(xs, ys), erased s : Sorted(ys)) {
  match xs : _ {
    Nil() => (Nil(), PermNil(), SortedNil());
    Cons(x, rest) => {
      let (zs, erased q, erased t) = sort(subterm rest);
      let (ws, erased i, erased u) = insert(x, zs, t);
      (ws, PermCons(_, _, _, _, q, i), u)
    };
  }
}

-- `goal` states the theorem, here as the signature a function must have: for
-- every list xs it returns a list ys, evidence that ys is a rearrangement of
-- xs, and evidence that ys is sorted. `qed sort` has the checker confirm that
-- sort is such a function. The page reports whether the goal is proved.
goal fn (xs : List())
    -> (ys : List(), erased p : Perm(xs, ys), erased s : Sorted(ys));
qed sort;

-- Code at the top level runs as soon as it is checked.
let one = Succ(Zero());
let two = Succ(one);
let three = Succ(two);
let (sorted, erased perm, erased proof) =
  sort(Cons(three, Cons(one, Cons(two, Cons(Zero(), Cons(one, Nil()))))));
-- `print` shows a value next to the statement. The second one shows
-- GeOrd(_, _, _): erased fields are not there at run time and print as `_`.
print sorted;
print compare(three, one);

-- Primality by reflection.
-- A program that decides whether a number is prime and returns a proof with its
-- answer. Running it on 4999 while the file is checked is then a proof that
-- 4999 is prime, one that nobody wrote by hand. Proving a fact by running a
-- verified program is called proof by reflection.
--
-- The file has four parts:
--   * What "prime" means, as types over unary numbers, Succ(Succ(... Zero())).
--     The goal is a check on that definition: if n is prime and a * b = n, then
--     a or b is 1.
--   * Facts about +, * and division. Each has a comment giving the fact. The
--     bodies are the proofs, and can be skipped on a first read.
--   * Binary subtraction and division, each returning evidence that ties its
--     result to the unary numbers.
--   * decidePrime. It counts k up from 2 to the square root of n, keeping a
--     list of the primes found so far. It tests each k, and at the end n, by
--     dividing by the listed primes p for which p * p is no bigger than the
--     number tested.
--
-- The unary numbers and all the evidence are erased, so only the binary
-- arithmetic is meant to run.
--
-- The unary and binary numbers, and many of the facts about + and *, are the
-- same as in the Binary arithmetic example. This file adds to each of them.
--
-- If Pledge is new to you:
--   * `data` declares a type and lists every way to build a value of it.
--   * A type can take values as parameters. `Plus(m, n, r)` below is a separate
--     type for each three numbers, and it is written so that a value of it can
--     be built only when m + n = r. So a value of type `Plus(m, n, r)` is
--     evidence, a proof, that m + n = r. Most types in this file are like that.
--   * A function that takes evidence and returns evidence is a proof that one
--     fact follows from others. The checker only accepts it if it covers every
--     case.
--   * `erased` marks what exists only for the checker. Running the program
--     skips it, so here the proofs cost nothing at run time.
--   * The Tutorial link at the top of the page teaches all of this in order.

-- Numbers in unary, built by hand: Zero(), then Succ(Zero()) for 1, and so on.
-- Everything applied is written with parentheses, even with no arguments.
data Nat() : Type() {
  Zero() : Nat();
  Succ(pred : Nat()) : Nat();
}

-- Eq(A, x, y) reads "x and y are the same value of type A". Its one
-- constructor, Refl, only builds Eq(A, x, x), so evidence exists only when the
-- two sides are the same.
data Eq(A : Type(), x : A, y : A) : Type() {
  Refl(erased A : Type(), erased x : A) : Eq(A, x, x);
}

-- A type with no constructors, so it has no values. A function that returns a
-- False() shows that its arguments cannot all exist together. This is how
-- "impossible" is said.
data False() : Type() {}

-- Or(A, B) reads "A or B": evidence of A (Inl) or evidence of B (Inr).
data Or(A : Type(), B : Type()) : Type() {
  Inl(erased A : Type(), erased B : Type(), x : A) : Or(A, B);
  Inr(erased A : Type(), erased B : Type(), y : B) : Or(A, B);
}

-- NonZero(n) reads "n is not zero".
data NonZero(n : Nat()) : Type() {
  NonZeroSucc(erased n : Nat()) : NonZero(Succ(n));
}

-- Plus(m, n, r) reads "m + n = r". Its two lines are the rules that define
-- addition: zero plus n is n, and (m + 1) + n = r + 1 whenever m + n = r.
--
-- Addition is written as a type because a Pledge type cannot contain a function
-- call. Another type can mention Plus(m, n, r); it could not mention
-- plus(m, n).
data Plus(m : Nat(), n : Nat(), r : Nat()) : Type() {
  PlusZero(erased n : Nat()) : Plus(Zero(), n, n);
  PlusSucc(erased m : Nat(), erased n : Nat(), erased r : Nat(),
      p : Plus(m, n, r)) : Plus(Succ(m), n, Succ(r));
}

-- Times(m, n, r) reads "m * n = r": zero times n is zero, and
-- (m + 1) * n = r + n whenever m * n = r.
data Times(m : Nat(), n : Nat(), r : Nat()) : Type() {
  TimesZero(erased n : Nat()) : Times(Zero(), n, Zero());
  TimesSucc(erased m : Nat(), erased n : Nat(), erased r : Nat(),
      erased s : Nat(), t : Times(m, n, r), p : Plus(r, n, s))
    : Times(Succ(m), n, s);
}

-- Cmp(m, n) says which holds: m >= n (CmpGe) or m < n (CmpLt). There is no
-- separate type for "less than". "n <= m" is said as Plus(n, k, m), "n plus
-- some k is m", and "m < n" as Plus(Succ(m), k, n). The whole file reads Plus
-- this way.
data Cmp(m : Nat(), n : Nat()) : Type() {
  CmpGe(erased m : Nat(), erased n : Nat(), erased k : Nat(), p : Plus(n, k, m))
    : Cmp(m, n);
  CmpLt(erased m : Nat(), erased n : Nat(), erased k : Nat(),
      p : Plus(Succ(m), k, n)) : Cmp(m, n);
}

-- DivMod(n, d, q, r) reads "n divided by d is q, remainder r": q * d = t,
-- t + r = n, and r < d.
data DivMod(n : Nat(), d : Nat(), q : Nat(), r : Nat()) : Type() {
  DivModIntro(erased n : Nat(), erased d : Nat(), erased q : Nat(),
      erased r : Nat(), erased t : Nat(), erased k : Nat(), tq : Times(q, d, t),
      s : Plus(t, r, n), l : Plus(Succ(r), k, d)) : DivMod(n, d, q, r);
}

-- NotDivides(d, n) reads "d does not divide n": dividing n by d leaves a
-- remainder that is a Succ, so not zero.
data NotDivides(d : Nat(), n : Nat()) : Type() {
  NotDiv(erased d : Nat(), erased n : Nat(), erased q : Nat(), erased r : Nat(),
      m : DivMod(n, d, q, Succ(r))) : NotDivides(d, n);
}

-- NoDivBelow(n, k) reads "no d with 2 <= d < k divides n". For k = 2 there is
-- nothing to show; each NoDivStep covers one more d.
data NoDivBelow(n : Nat(), k : Nat()) : Type() {
  NoDivTwo(erased n : Nat()) : NoDivBelow(n, Succ(Succ(Zero())));
  NoDivStep(erased n : Nat(), erased k : Nat(), rest : NoDivBelow(n, k),
      nd : NotDivides(k, n)) : NoDivBelow(n, Succ(k));
}

-- Prime(n) reads "n is prime": no d with 2 <= d < n divides n. NoDivBelow can
-- only be built for k >= 2, so n >= 2 is included.
data Prime(n : Nat()) : Type() {
  PrimeIntro(erased n : Nat(), nd : NoDivBelow(n, n)) : Prime(n);
}

-- A positive number in binary, lowest digit outermost. One() is 1, P0(p) is p
-- with a 0 written after it (twice p), and P1(p) is p with a 1 written after it
-- (twice p, plus 1). So 6, binary 110, is P0(P1(One())).
-- ---- Binary numbers, and the types the search uses ----

data Pos() : Type() {
  One() : Pos();
  P0(p : Pos()) : Pos();
  P1(p : Pos()) : Pos();
}

-- Zero, or a positive number. Keeping zero apart leaves no room for leading
-- zeros, so a number has only one binary form.
data Bin() : Type() {
  BZ() : Bin();
  BP(p : Pos()) : Bin();
}

-- PosRep(p, n) reads "binary p and unary n are the same number". Plus(n, n, d)
-- is how "d is twice n" is said.
data PosRep(p : Pos(), n : Nat()) : Type() {
  RepOne() : PosRep(One(), Succ(Zero()));
  RepP0(erased p : Pos(), erased n : Nat(), erased d : Nat(), r : PosRep(p, n),
      s : Plus(n, n, d)) : PosRep(P0(p), d);
  RepP1(erased p : Pos(), erased n : Nat(), erased d : Nat(), r : PosRep(p, n),
      s : Plus(n, n, d)) : PosRep(P1(p), Succ(d));
}

-- The same for Bin.
data Rep(b : Bin(), n : Nat()) : Type() {
  RepZ() : Rep(BZ(), Zero());
  RepP(erased p : Pos(), erased n : Nat(), r : PosRep(p, n)) : Rep(BP(p), n);
}

-- The result of subtracting n from m in binary. Above holds the difference z, a
-- binary number that stands for the k with n + k = m. Below says that m < n,
-- and holds nothing at run time.
data Diff(m : Nat(), n : Nat()) : Type() {
  Above(z : Bin(), erased m : Nat(), erased n : Nat(), erased k : Nat(),
      erased r : Rep(z, k), erased p : Plus(n, k, m)) : Diff(m, n);
  Below(erased m : Nat(), erased n : Nat(), erased k : Nat(),
      erased p : Plus(Succ(m), k, n)) : Diff(m, n);
}

-- A list of unary numbers.
data NatList() : Type() {
  NNil() : NatList();
  NCons(head : Nat(), tail : NatList()) : NatList();
}

-- Mem(x, l) reads "x is an element of l".
data Mem(x : Nat(), l : NatList()) : Type() {
  Here(erased x : Nat(), erased l : NatList()) : Mem(x, NCons(x, l));
  There(erased x : Nat(), erased y : Nat(), erased l : NatList(), m : Mem(x, l))
    : Mem(x, NCons(y, l));
}

-- Factor(d, n) reads "d is a proper factor of n": q * d = n for some q, with
-- 2 <= d and d < n.
data Factor(d : Nat(), n : Nat()) : Type() {
  FactorIntro(erased d : Nat(), erased n : Nat(), erased q : Nat(),
      erased a : Nat(), erased b : Nat(), t : Times(q, d, n),
      lo : Plus(Succ(Succ(Zero())), a, d), hi : Plus(Succ(d), b, n))
    : Factor(d, n);
}

-- PrimesBelow(l, k) reads "l holds exactly the primes below k", newest first.
-- It is built one k at a time: k is added with evidence that it is prime, or
-- skipped with evidence that it has a proper factor.
data PrimesBelow(l : NatList(), k : Nat()) : Type() {
  PrimesTwo() : PrimesBelow(NNil(), Succ(Succ(Zero())));
  PrimesAdd(erased l : NatList(), erased k : Nat(), rest : PrimesBelow(l, k),
      p : Prime(k)) : PrimesBelow(NCons(k, l), Succ(k));
  PrimesSkip(erased l : NatList(), erased k : Nat(), erased d : Nat(),
      rest : PrimesBelow(l, k), f : Factor(d, k)) : PrimesBelow(l, Succ(k));
}

-- BelowSquare(m, k) reads "m < k * k".
data BelowSquare(m : Nat(), k : Nat()) : Type() {
  BelowSquareIntro(erased m : Nat(), erased k : Nat(), erased kk : Nat(),
      erased w : Nat(), t : Times(k, k, kk), p : Plus(Succ(m), w, kk))
    : BelowSquare(m, k);
}

-- Checked(l, m) reads "each p in l does not divide m, or is too big to matter:
-- m < p * p".
data Checked(l : NatList(), m : Nat()) : Type() {
  CheckedNil(erased m : Nat()) : Checked(NNil(), m);
  CheckedCons(erased p : Nat(), erased l : NatList(), erased m : Nat(),
      rest : Checked(l, m), o : Or(NotDivides(p, m), BelowSquare(m, p)))
    : Checked(NCons(p, l), m);
}

-- The list that exists at run time: the same primes in binary. Erased evidence
-- ties each to its entry in the erased unary list l.
data PList(l : NatList()) : Type() {
  PNil() : PList(NNil());
  PCons(p : Pos(), erased n : Nat(), erased r : PosRep(p, n),
      erased l : NatList(), rest : PList(l)) : PList(NCons(n, l));
}

-- The result of trying the listed primes on m. Found: a factor d. Pass: every
-- prime on the list was checked. Stop: the same, and also m < k * k, so no
-- larger prime needs trying.
data Trial(l : NatList(), m : Nat(), k : Nat()) : Type() {
  Found(erased l : NatList(), erased m : Nat(), erased k : Nat(), d : Bin(),
      erased e : Nat(), erased r : Rep(d, e), erased f : Factor(e, m))
    : Trial(l, m, k);
  Pass(erased l : NatList(), erased m : Nat(), erased k : Nat(),
      erased c : Checked(l, m)) : Trial(l, m, k);
  Stop(erased l : NatList(), erased m : Nat(), erased k : Nat(),
      erased c : Checked(l, m), erased u : BelowSquare(m, k)) : Trial(l, m, k);
}

-- decidePrime's answer: prime, with an erased proof; composite, with a factor d
-- that is there at run time; or below two.
data Verdict(n : Nat()) : Type() {
  IsPrime(erased n : Nat(), erased p : Prime(n)) : Verdict(n);
  Composite(erased n : Nat(), d : Bin(), erased e : Nat(), erased r : Rep(d, e),
      erased f : Factor(e, n)) : Verdict(n);
  BelowTwo(erased n : Nat(), erased k : Nat(),
      erased p : Plus(Succ(n), k, Succ(Succ(Zero())))) : Verdict(n);
}


-- `goal` states the theorem, here as the signature a function must have: given
-- evidence that n is prime and that a * b = n, it returns evidence that a = 1
-- or b = 1. `qed primeFactor`, further down, has the checker confirm that
-- primeFactor is such a function. The page reports whether the goal is proved.
goal fn (erased n : Nat(), erased a : Nat(), erased b : Nat(),
    erased p : Prime(n), erased t : Times(a, b, n))
    -> (erased o : Or(Eq(Nat(), a, Succ(Zero())), Eq(Nat(), b, Succ(Zero()))));

-- ---- Facts about + ----

-- Adds two unary numbers. The sum is erased: this is for naming a sum inside a
-- proof, and is not meant to run.
--
-- `subterm` is how a recursive function shows that it ends: each recursive call
-- must pass, for that parameter, a piece of the caller's own argument. Here
-- that is k, the inside of m = Succ(k). The checker demands this of every
-- recursive function; one that might loop forever is rejected.
--
-- `match m : _` : after the colon comes what the match produces, and `_` leaves
-- it to the checker, which knows it from the return type. As an argument, `_`
-- is an erased value the checker can work out for itself.
fn plus(subterm m : Nat(), n : Nat())
    -> (erased r : Nat(), erased p : Plus(m, n, r)) {
  match m : _ {
    Zero() => (n, PlusZero(_));
    Succ(k) => {
      let (erased r, erased p) = plus(subterm k, n);
      (Succ(r), PlusSucc(_, _, _, p))
    };
  }
}

-- n + 0 = n. (The definition only gives 0 + n = n.)
fn plusZeroRight(subterm n : Nat()) -> (erased p : Plus(n, Zero(), n)) {
  match n : _ {
    Zero() => PlusZero(_);
    Succ(k) => PlusSucc(_, _, _, plusZeroRight(subterm k));
  }
}

-- If m + n = r then m + (n + 1) = r + 1. The recursion is on p, the evidence:
-- evidence is data like any other and can be matched on and recursed over.
fn plusSucc(erased m : Nat(), erased n : Nat(), erased r : Nat(),
    subterm p : Plus(m, n, r))
    -> (erased q : Plus(m, Succ(n), Succ(r))) {
  match p : _ {
    PlusZero(_) => PlusZero(_);
    PlusSucc(_, _, _, p1) => PlusSucc(_, _, _, plusSucc(_, _, _, subterm p1));
  }
}

-- If m + n = r then n + m = r.
fn plusComm(erased m : Nat(), erased n : Nat(), erased r : Nat(),
    subterm p : Plus(m, n, r))
    -> (erased q : Plus(n, m, r)) {
  match p : _ {
    PlusZero(_) => plusZeroRight(n);
    PlusSucc(_, _, _, p1) => plusSucc(_, _, _, plusComm(_, _, _, subterm p1));
  }
}

-- (a + b) + c = a + (b + c). A type cannot contain +, so every sum needs a
-- name: ab for a + b, bc for b + c. That is why these facts take so many
-- parameters.
fn plusAssoc(erased a : Nat(), erased b : Nat(), erased c : Nat(),
    erased ab : Nat(), erased r : Nat(), subterm p : Plus(a, b, ab),
    q : Plus(ab, c, r))
    -> (erased bc : Nat(), erased q1 : Plus(b, c, bc),
        erased q2 : Plus(a, bc, r)) {
  match p : _ {
    PlusZero(_) => (r, q, PlusZero(_));
    PlusSucc(_, _, _, p1) => {
      -- A `let` with a constructor on the left takes a value apart. It is
      -- accepted only when the value can have been built no other way. In this
      -- branch ab is a Succ, and PlusZero only talks about Zero() + n, so q
      -- must be a PlusSucc.
      let PlusSucc(_, _, _, q3) = q;
      let (erased bc, erased s1, erased s2) =
        plusAssoc(_, _, _, _, _, subterm p1, q3);
      (bc, s1, PlusSucc(_, _, _, s2))
    };
  }
}

-- The same, read from right to left.
fn plusAssocRev(erased a : Nat(), erased b : Nat(), erased c : Nat(),
    erased bc : Nat(), erased r : Nat(), p : Plus(b, c, bc),
    subterm q : Plus(a, bc, r))
    -> (erased ab : Nat(), erased q1 : Plus(a, b, ab),
        erased q2 : Plus(ab, c, r)) {
  match q : _ {
    PlusZero(_) => (b, PlusZero(_), p);
    PlusSucc(_, _, _, q3) => {
      let (erased ab, erased s1, erased s2) =
        plusAssocRev(_, _, _, _, _, p, subterm q3);
      (Succ(ab), PlusSucc(_, _, _, s1), PlusSucc(_, _, _, s2))
    };
  }
}

-- (w + y) + (x + z) = (w + x) + (y + z).
fn exchange(erased w : Nat(), erased y : Nat(), erased x : Nat(),
    erased z : Nat(), erased wy : Nat(), erased xz : Nat(), erased r : Nat(),
    p : Plus(w, y, wy), q : Plus(x, z, xz), s : Plus(wy, xz, r))
    -> (erased wx : Nat(), erased yz : Nat(), erased p1 : Plus(w, x, wx),
        erased q1 : Plus(y, z, yz), erased s1 : Plus(wx, yz, r)) {
  let (erased yxz, erased s2, erased s3) = plusAssoc(_, _, _, _, _, p, s);
  let (erased yx, erased s4, erased s5) = plusAssocRev(_, _, _, _, _, q, s2);
  let (erased yz, erased s7, erased s8) =
    plusAssoc(_, _, _, _, _, plusComm(_, _, _, s4), s5);
  let (erased wx, erased s9, erased s10) = plusAssocRev(_, _, _, _, _, s8, s3);
  (wx, yz, s9, s7, s10)
}

-- A sum has one value: if a + b = c and a + b = d, then c = d.
fn plusFunc(erased a : Nat(), erased b : Nat(), erased c : Nat(),
    erased d : Nat(), subterm p : Plus(a, b, c), q : Plus(a, b, d))
    -> (erased e : Eq(Nat(), c, d)) {
  match p : _ {
    PlusZero(_) => {
      let PlusZero(_) = q;
      Refl(_, _)
    };
    PlusSucc(_, _, _, p1) => {
      let PlusSucc(_, _, _, q1) = q;
      -- The recursive call returns evidence that the two smaller sums are
      -- equal. An equation is used by matching on its evidence: Refl only
      -- builds Eq(A, x, x), so inside the branch the checker treats the two
      -- sides as one value. Then c and d are visibly the same, and Refl is
      -- accepted as the result.
      match erased plusFunc(_, _, _, _, subterm p1, q1) : _ {
        Refl(_, _) => Refl(_, _);
      }
    };
  }
}

-- If a + b = c and a + d = c then b = d.
fn plusCancel(erased a : Nat(), erased b : Nat(), erased c : Nat(),
    erased d : Nat(), subterm p : Plus(a, b, c), q : Plus(a, d, c))
    -> (erased e : Eq(Nat(), b, d)) {
  match p : _ {
    PlusZero(_) => {
      let PlusZero(_) = q;
      Refl(_, _)
    };
    PlusSucc(_, _, _, p1) => {
      let PlusSucc(_, _, _, q1) = q;
      plusCancel(_, _, _, _, subterm p1, q1)
    };
  }
}

-- If (a + 1) + b = c then a + (b + 1) = c.
fn plusMove(erased a : Nat(), erased b : Nat(), erased c : Nat(),
    p : Plus(Succ(a), b, c))
    -> (erased q : Plus(a, Succ(b), c)) {
  let PlusSucc(_, _, _, p1) = p;
  plusSucc(_, _, _, p1)
}

-- The same, the other way.
fn plusMoveBack(erased a : Nat(), erased b : Nat(), erased c : Nat(),
    p : Plus(a, Succ(b), c))
    -> (erased q : Plus(Succ(a), b, c)) {
  let erased PlusSucc(_, _, _, p1) = plusComm(_, _, _, p);
  PlusSucc(_, _, _, plusComm(_, _, _, p1))
}

-- If a + b = c then (a + 1) + (b + 1) = c + 2.
fn succBoth(erased a : Nat(), erased b : Nat(), erased c : Nat(),
    p : Plus(a, b, c))
    -> (erased q : Plus(Succ(a), Succ(b), Succ(Succ(c)))) {
  PlusSucc(_, _, _, plusSucc(_, _, _, p))
}

-- a + (b + 1) = a is impossible.
fn noGrow(erased a : Nat(), erased b : Nat(), subterm p : Plus(a, Succ(b), a))
    -> (erased f : False()) {
  match p : _ {
    PlusSucc(_, _, _, p1) => noGrow(_, _, subterm p1);
  }
}

-- a <= b and b < a cannot both hold.
fn antisym(erased a : Nat(), erased b : Nat(), erased i : Nat(),
    erased w : Nat(), p : Plus(a, i, b), q : Plus(b, Succ(w), a))
    -> (erased f : False()) {
  let (erased c, erased p1, erased p2) = plusAssoc(_, _, _, _, _, p, q);
  let erased PlusSucc(_, _, _, _) = plusComm(_, _, _, p1);
  noGrow(_, _, p2)
}

-- For any m and n, either m >= n or m < n. Everything here is erased: it is
-- used to split a proof into two cases.
fn compare(subterm m : Nat(), n : Nat()) -> (erased o : Cmp(m, n)) {
  match m : _ {
    Zero() => match n : _ {
      Zero() => CmpGe(_, _, Zero(), PlusZero(_));
      Succ(n1) => CmpLt(_, _, n1, PlusSucc(_, _, _, PlusZero(_)));
    };
    Succ(m1) => match n : _ {
      Zero() => CmpGe(_, _, m, PlusZero(_));
      Succ(n1) => match erased compare(subterm m1, n1) : _ {
        CmpGe(_, _, k, p) => CmpGe(_, _, k, PlusSucc(_, _, _, p));
        CmpLt(_, _, k, p) => CmpLt(_, _, k, PlusSucc(_, _, _, p));
      };
    };
  }
}

-- If a + b = r then 2a + 2b = 2r.
fn dsum(erased a : Nat(), erased b : Nat(), erased r : Nat(), erased ma : Nat(),
    erased nb : Nat(), erased mr : Nat(), p : Plus(a, b, r),
    pa : Plus(a, a, ma), pb : Plus(b, b, nb), pr : Plus(r, r, mr))
    -> (erased q : Plus(ma, nb, mr)) {
  let (erased d, erased s) = plus(ma, nb);
  let (erased wx, erased yz, erased p1, erased p2, erased q) =
    exchange(_, _, _, _, _, _, _, pa, pb, s);
  match erased plusFunc(_, _, _, _, p1, p) : _ {
    Refl(_, _) => match erased plusFunc(_, _, _, _, p2, p) : _ {
      Refl(_, _) => match erased plusFunc(_, _, _, _, q, pr) : _ {
        Refl(_, _) => s;
      };
    };
  }
}

-- If a < b then 2a + 2 <= 2b.
fn ltDouble(erased a : Nat(), erased b : Nat(), erased k : Nat(),
    erased a2 : Nat(), erased b2 : Nat(), l : Plus(Succ(a), k, b),
    sa : Plus(a, a, a2), sb : Plus(b, b, b2))
    -> (erased w : Nat(), erased p : Plus(Succ(Succ(a2)), w, b2)) {
  let (erased w, erased sk) = plus(k, k);
  (w, dsum(_, _, _, _, _, _, l, succBoth(_, _, _, sa), sk, sb))
}

-- ---- Facts about * ----

-- m * 0 = 0.
fn timesZeroRight(subterm m : Nat()) -> (erased t : Times(m, Zero(), Zero())) {
  match m : _ {
    Zero() => TimesZero(_);
    Succ(k) => TimesSucc(_, _, _, _, timesZeroRight(subterm k), PlusZero(_));
  }
}

-- (a + b) * n = a * n + b * n.
fn timesPlusLeft(erased a : Nat(), erased b : Nat(), erased c : Nat(),
    erased n : Nat(), erased ta : Nat(), erased tb : Nat(), erased t : Nat(),
    subterm p : Plus(a, b, c), t1 : Times(a, n, ta), t2 : Times(b, n, tb),
    q : Plus(ta, tb, t))
    -> (erased u : Times(c, n, t)) {
  match p : _ {
    PlusZero(_) => {
      let TimesZero(_) = t1;
      let PlusZero(_) = q;
      t2
    };
    PlusSucc(_, _, _, p1) => {
      let TimesSucc(_, _, _, _, t3, s1) = t1;
      let (erased ntb, erased s2, erased s3) = plusAssoc(_, _, _, _, _, s1, q);
      let (erased x, erased s4, erased s5) =
        plusAssocRev(_, _, _, _, _, plusComm(_, _, _, s2), s3);
      TimesSucc(_, _, _, _,
          timesPlusLeft(_, _, _, _, _, _, _, subterm p1, t3, t2, s4), s5)
    };
  }
}

-- (2a) * n = 2 * (a * n).
fn timesDouble(erased a : Nat(), erased ma : Nat(), erased n : Nat(),
    erased t : Nat(), sa : Plus(a, a, ma), u : Times(a, n, t))
    -> (erased d : Nat(), erased q : Plus(t, t, d),
        erased v : Times(ma, n, d)) {
  let (erased d, erased q) = plus(t, t);
  (d, q, timesPlusLeft(_, _, _, _, _, _, _, sa, u, u, q))
}

-- The same fact used the other way: a product (a + k) * d splits into a * d and
-- k * d.
fn timesSplit(erased a : Nat(), erased k : Nat(), erased a2 : Nat(),
    erased d : Nat(), erased n : Nat(), subterm p : Plus(a, k, a2),
    t : Times(a2, d, n))
    -> (erased x : Nat(), erased y : Nat(), erased tx : Times(a, d, x),
        erased ty : Times(k, d, y), erased s : Plus(x, y, n)) {
  match p : _ {
    PlusZero(_) => (Zero(), n, TimesZero(_), t, PlusZero(_));
    PlusSucc(_, _, _, p1) => {
      let TimesSucc(_, _, _, _, t1, q) = t;
      let (erased x, erased y, erased tx, erased ty, erased s) =
        timesSplit(_, _, _, _, _, subterm p1, t1);
      let (erased yd, erased s2, erased s3) = plusAssoc(_, _, _, _, _, s, q);
      let (erased x1, erased s4, erased s5) =
        plusAssocRev(_, _, _, _, _, plusComm(_, _, _, s2), s3);
      (x1, y, TimesSucc(_, _, _, _, tx, s4), ty, s5)
    };
  }
}

-- A product has one value: if a * b = x and a * b = y, then x = y.
fn timesFunc(erased a : Nat(), erased b : Nat(), erased x : Nat(),
    erased y : Nat(), subterm t : Times(a, b, x), u : Times(a, b, y))
    -> (erased e : Eq(Nat(), x, y)) {
  match t : _ {
    TimesZero(_) => {
      let TimesZero(_) = u;
      Refl(_, _)
    };
    TimesSucc(_, _, _, _, t1, p1) => {
      let TimesSucc(_, _, _, _, u1, q1) = u;
      match erased timesFunc(_, _, _, _, subterm t1, u1) : _ {
        Refl(_, _) => plusFunc(_, _, _, _, p1, q1);
      }
    };
  }
}

-- a * (b + 1) = a * b + a.
fn timesSuccRight(erased a : Nat(), erased b : Nat(), erased n : Nat(),
    subterm t : Times(a, b, n))
    -> (erased r : Nat(), erased u : Times(a, Succ(b), r),
        erased p : Plus(n, a, r)) {
  match t : _ {
    TimesZero(_) => (Zero(), TimesZero(_), PlusZero(_));
    TimesSucc(_, _, _, _, t1, p1) => {
      let (erased r1, erased u1, erased q1) =
        timesSuccRight(_, _, _, subterm t1);
      let (erased r, erased q2) = plus(r1, Succ(b));
      let (erased x, erased q3, erased q4) = plusAssoc(_, _, _, _, _, q1, q2);
      let erased PlusSucc(_, _, _, q5) = plusComm(_, _, _, q3);
      let (erased y, erased q6, erased q7) =
        plusAssocRev(_, _, _, _, _, plusSucc(_, _, _, q5), q4);
      match erased plusFunc(_, _, _, _, q6, p1) : _ {
        Refl(_, _) => (r, TimesSucc(_, _, _, _, u1, q2), q7);
      }
    };
  }
}

-- If a * b = n then b * a = n.
fn timesComm(erased a : Nat(), erased b : Nat(), erased n : Nat(),
    subterm t : Times(a, b, n))
    -> (erased u : Times(b, a, n)) {
  match t : _ {
    TimesZero(_) => timesZeroRight(b);
    TimesSucc(_, _, _, _, t1, p1) => {
      let (erased r, erased u1, erased q1) =
        timesSuccRight(_, _, _, timesComm(_, _, _, subterm t1));
      match erased plusFunc(_, _, _, _, q1, p1) : _ {
        Refl(_, _) => u1;
      }
    };
  }
}

-- ---- Division, and the goal ----

-- Any n can be divided by any nonzero d, with a remainder below d. This is
-- unary and erased: it is for use inside proofs and is not meant to run.
fn divmod(subterm n : Nat(), d : Nat(), z : NonZero(d))
    -> (erased q : Nat(), erased r : Nat(), erased dm : DivMod(n, d, q, r)) {
  match n : _ {
    Zero() => {
      let NonZeroSucc(d1) = z;
      (Zero(), Zero(),
          DivModIntro(_, _, _, _, Zero(), d1, TimesZero(_), PlusZero(_),
              PlusSucc(_, _, _, PlusZero(_))))
    };
    Succ(n1) => {
      let (erased q, erased r, erased dm) = divmod(subterm n1, d, z);
      let erased DivModIntro(_, _, _, _, t, _, tq, s, l) = dm;
      match erased plusComm(_, _, _, l) : _ {
        PlusZero(_) => (Succ(q), Zero(),
            DivModIntro(_, _, _, _, n, r,
                TimesSucc(_, _, _, _, tq, plusSucc(_, _, _, s)),
                plusZeroRight(n), PlusSucc(_, _, _, PlusZero(_))));
        PlusSucc(k1, _, _, l1) => (q, Succ(r),
            DivModIntro(_, _, _, _, t, k1, tq, plusSucc(_, _, _, s),
                PlusSucc(_, _, _, plusComm(_, _, _, l1))));
      }
    };
  }
}

-- NoDivBelow(n, k) only exists for k >= 2.
fn ndTwo(erased n : Nat(), erased k : Nat(), subterm nd : NoDivBelow(n, k))
    -> (erased j : Nat(), erased e : Eq(Nat(), k, Succ(Succ(j)))) {
  match nd : _ {
    NoDivTwo(_) => (Zero(), Refl(_, _));
    NoDivStep(_, _, rest, _) => {
      let (erased j, erased e) = ndTwo(_, _, subterm rest);
      match erased e : _ {
        Refl(_, _) => (Succ(j), Refl(_, _));
      }
    };
  }
}

-- Takes one fact out of NoDivBelow(n, k): a d with 2 <= d < k does not divide
-- n. The d here is written Succ(Succ(d)).
fn lookup(erased n : Nat(), erased d : Nat(), erased k : Nat(),
    erased j : Nat(), subterm nd : NoDivBelow(n, k),
    p : Plus(Succ(Succ(Succ(d))), j, k))
    -> (erased r : NotDivides(Succ(Succ(d)), n)) {
  match nd : _ {
    NoDivTwo(_) => {
      let PlusSucc(_, _, _, p1) = p;
      let PlusSucc(_, _, _, p2) = p1;
      -- A match with no branches says "this cannot happen", and the checker has
      -- to agree. Here p2 would say that (d + 1) + j = 0, and neither rule of
      -- Plus builds that.
      match p2 : _ {}
    };
    NoDivStep(_, _, rest, nd1) => {
      let PlusSucc(_, _, _, p1) = p;
      match erased plusComm(_, _, _, p1) : _ {
        PlusZero(_) => nd1;
        PlusSucc(_, _, _, p2) => lookup(_, _, _, _, subterm rest,
            PlusSucc(_, _, _, plusComm(_, _, _, p2)));
      }
    };
  }
}

-- If dividing n by d leaves a remainder that is not zero, then n is not a * d
-- for any a.
fn divUniqueFalse(erased n : Nat(), erased d : Nat(), erased q : Nat(),
    erased r : Nat(), erased a : Nat(), dm : DivMod(n, d, q, Succ(r)),
    t : Times(a, d, n))
    -> (erased f : False()) {
  let DivModIntro(_, _, _, _, _, _, tq, s, l) = dm;
  match erased compare(a, q) : _ {
    CmpGe(_, _, _, p) => {
      let (erased x, erased y, erased tx, erased ty, erased sxy) =
        timesSplit(_, _, _, _, _, p, t);
      match erased timesFunc(_, _, _, _, tq, tx) : _ {
        Refl(_, _) => match erased plusCancel(_, _, _, _, s, sxy) : _ {
          Refl(_, _) => {
            let erased TimesSucc(_, _, _, _, _, pu) = ty;
            antisym(_, _, _, _, plusComm(_, _, _, pu), plusMove(_, _, _, l))
          };
        };
      }
    };
    CmpLt(_, _, _, p) => {
      let (erased x, erased y, erased tx, erased ty, erased sxy) =
        timesSplit(_, _, _, _, _, p, tq);
      let erased TimesSucc(_, _, _, _, tu, pu) = tx;
      match erased timesFunc(_, _, _, _, t, tu) : _ {
        Refl(_, _) => {
          let (erased z, erased p1, erased p2) =
            plusAssoc(_, _, _, _, _, pu, sxy);
          antisym(_, _, _, _, p2, s)
        };
      }
    };
  }
}

-- So when NoDivBelow(n, k) holds, no d with 2 <= d < k is a factor of n.
fn noFactor(erased n : Nat(), erased d : Nat(), erased k : Nat(),
    erased j : Nat(), erased a : Nat(), nd : NoDivBelow(n, k),
    p : Plus(Succ(Succ(Succ(d))), j, k), t : Times(a, Succ(Succ(d)), n))
    -> (erased f : False()) {
  let erased NotDiv(_, _, _, _, dm) = lookup(_, _, _, _, nd, p);
  divUniqueFalse(_, _, _, _, _, dm, t)
}

-- The goal. By cases on b: 0 is impossible, 1 is the answer, and a b from 2 up
-- is either below n, which Prime(n) rules out, or at least n, which leaves only
-- a = 1. Each `match ... {}` is a case shown to be impossible.
fn primeFactor(erased n : Nat(), erased a : Nat(), erased b : Nat(),
    erased p : Prime(n), erased t : Times(a, b, n))
    -> (erased o : Or(Eq(Nat(), a, Succ(Zero())), Eq(Nat(), b, Succ(Zero())))) {
  let erased PrimeIntro(_, nd) = p;
  let (erased n2, erased e) = ndTwo(_, _, nd);
  match erased e : _ {
    Refl(_, _) => match erased b : _ {
      Zero() => match erased timesFunc(_, _, _, _, t, timesZeroRight(a)) : _ {};
      Succ(b1) => match erased b1 : _ {
        Zero() => Inr(_, _, Refl(Nat(), b));
        Succ(b2) => match erased compare(b, n) : _ {
          CmpLt(_, _, _, lt) =>
            match erased noFactor(_, _, _, _, _, nd, lt, t) : _ {};
          CmpGe(_, _, _, ge) => match erased a : _ {
            Zero() => match erased t : _ {};
            Succ(a1) => match erased a1 : _ {
              Zero() => Inl(_, _, Refl(Nat(), a));
              Succ(a2) => {
                let erased TimesSucc(_, _, _, _, t1, p1) = t;
                let erased TimesSucc(_, _, _, _, _, p2) = t1;
                let erased PlusSucc(_, _, _, _) = plusComm(_, _, _, p2);
                match erased antisym(_, _, _, _, ge,
                    plusComm(_, _, _, p1)) : _ {}
              };
            };
          };
        };
      };
    };
  }
}

qed primeFactor;

-- ---- Facts for the search ----
-- What the proof of decidePrime needs: squares, and how a list of primes rules
-- out divisors.

-- Multiplies two unary numbers. Erased, like plus: it names a product inside a
-- proof.
fn times(subterm m : Nat(), n : Nat())
    -> (erased r : Nat(), erased t : Times(m, n, r)) {
  match m : _ {
    Zero() => (Zero(), TimesZero(_));
    Succ(k) => {
      let (erased r, erased t) = times(subterm k, n);
      let (erased s, erased p) = plus(r, n);
      (s, TimesSucc(_, _, _, _, t, p))
    };
  }
}

-- If j divides m and i divides j, then i divides m.
fn timesAssoc(erased q : Nat(), erased j : Nat(), erased m : Nat(),
    erased q2 : Nat(), erased i : Nat(), subterm t : Times(q, j, m),
    u : Times(q2, i, j))
    -> (erased c : Nat(), erased v : Times(c, i, m)) {
  match t : _ {
    TimesZero(_) => (Zero(), TimesZero(_));
    TimesSucc(_, _, _, _, t1, p1) => {
      let (erased c, erased v) = timesAssoc(_, _, _, _, _, subterm t1, u);
      let (erased c2, erased s) = plus(c, q2);
      (c2, timesPlusLeft(_, _, _, _, _, _, _, s, v, u, p1))
    };
  }
}

-- If a <= b then a * a <= b * b.
fn squareMono(erased a : Nat(), erased i : Nat(), erased b : Nat(),
    erased aa : Nat(), erased bb : Nat(), le : Plus(a, i, b),
    ta : Times(a, a, aa), tb : Times(b, b, bb))
    -> (erased z : Nat(), erased p : Plus(aa, z, bb)) {
  let (erased x, erased y, erased tx, erased ty, erased s) =
    timesSplit(_, _, _, _, _, le, tb);
  let (erased x1, erased y1, erased tx1, erased ty1, erased s1) =
    timesSplit(_, _, _, _, _, le, timesComm(_, _, _, tx));
  match erased timesFunc(_, _, _, _, ta, tx1) : _ {
    Refl(_, _) => {
      let (erased z, erased q1, erased q2) = plusAssoc(_, _, _, _, _, s1, s);
      (z, q2)
    };
  }
}

-- (k + 1) * (k + 1) = k * k + 2k + 1.
fn squareStep(erased k : Nat(), erased kk : Nat(), erased d : Nat(),
    erased kk1 : Nat(), t : Times(k, k, kk), dd : Plus(k, k, d),
    s : Plus(kk, Succ(d), kk1))
    -> (erased t1 : Times(Succ(k), Succ(k), kk1)) {
  let (erased r, erased u, erased q) = timesSuccRight(_, _, _, t);
  let (erased ab, erased s1, erased s2) =
    plusAssocRev(_, _, _, _, _, plusSucc(_, _, _, dd), s);
  match erased plusFunc(_, _, _, _, s1, q) : _ {
    Refl(_, _) => TimesSucc(_, _, _, _, u, s2);
  }
}

-- k < k * k for every k >= 2.
fn ltSquare(erased a : Nat(), erased kk : Nat(),
    t : Times(Succ(Succ(a)), Succ(Succ(a)), kk))
    -> (erased w : Nat(), erased p : Plus(Succ(Succ(Succ(a))), w, kk)) {
  let TimesSucc(_, _, _, _, t1, p1) = t;
  let TimesSucc(_, _, _, _, _, p2) = t1;
  let erased PlusSucc(_, _, w, _) = plusComm(_, _, _, p2);
  (w, plusMoveBack(_, _, _, plusComm(_, _, _, p1)))
}

-- If r < p then t + r < t + p.
fn succLess(erased t : Nat(), erased r : Nat(), erased m : Nat(),
    erased k : Nat(), erased p : Nat(), erased x : Nat(), s : Plus(t, r, m),
    l : Plus(Succ(r), k, p), q : Plus(t, p, x))
    -> (erased lt : Plus(Succ(m), k, x)) {
  let (erased ab, erased s1, erased s2) = plusAssocRev(_, _, _, _, _, l, q);
  match erased plusFunc(_, _, _, _, s1, plusSucc(_, _, _, s)) : _ {
    Refl(_, _) => s2;
  }
}

-- If m < a * a and a < k then m < k * k.
fn belowSquareUp(erased m : Nat(), erased a : Nat(), erased w : Nat(),
    erased k : Nat(), u : BelowSquare(m, a), lt : Plus(Succ(a), w, k))
    -> (erased v : BelowSquare(m, k)) {
  let BelowSquareIntro(_, _, _, _, ta, la) = u;
  let (erased kk, erased tk) = times(k, k);
  let (erased z, erased mono) =
    squareMono(_, _, _, _, _, plusMove(_, _, _, lt), ta, tk);
  let (erased vz, erased q1, erased q2) = plusAssoc(_, _, _, _, _, la, mono);
  BelowSquareIntro(_, _, _, _, tk, q2)
}

-- m < k * k, k <= j and j * j <= m cannot all hold.
fn notBelowSquare(erased m : Nat(), erased k : Nat(), erased i : Nat(),
    erased j : Nat(), erased x : Nat(), erased y : Nat(), u : BelowSquare(m, k),
    le : Plus(k, i, j), tj : Times(j, j, x), s : Plus(x, y, m))
    -> (erased f : False()) {
  let BelowSquareIntro(_, _, _, _, tk, lk) = u;
  let (erased z, erased mono) = squareMono(_, _, _, _, _, le, tk, tj);
  let (erased zy, erased q1, erased q2) = plusAssoc(_, _, _, _, _, mono, s);
  antisym(_, _, _, _, q2, plusMove(_, _, _, lk))
}

-- If dividing m by p gives a quotient below p, then m < p * p.
fn divBig(erased m : Nat(), erased p : Nat(), erased q : Nat(),
    erased r : Nat(), erased i : Nat(), dm : DivMod(m, p, q, r),
    lt : Plus(Succ(q), i, p))
    -> (erased u : BelowSquare(m, p)) {
  let DivModIntro(_, _, _, _, _, _, tq, s, l) = dm;
  let (erased pp, erased tp) = times(p, p);
  let (erased x, erased y, erased tx, erased ty, erased sxy) =
    timesSplit(_, _, _, _, _, lt, tp);
  let TimesSucc(_, _, _, _, t1, p1) = tx;
  match erased timesFunc(_, _, _, _, tq, t1) : _ {
    Refl(_, _) => {
      let (erased z, erased q1, erased q2) =
        plusAssoc(_, _, _, _, _, succLess(_, _, _, _, _, _, s, l, p1), sxy);
      BelowSquareIntro(_, _, _, _, tp, q2)
    };
  }
}

-- A division with remainder zero means q * d = m exactly.
fn exactTimes(erased m : Nat(), erased d : Nat(), erased q : Nat(),
    dm : DivMod(m, d, q, Zero()))
    -> (erased t : Times(q, d, m)) {
  let DivModIntro(_, _, _, _, t, _, tq, s, _) = dm;
  match erased plusFunc(_, _, _, _, plusZeroRight(t), s) : _ {
    Refl(_, _) => tq;
  }
}

-- A prime p that divides m with a quotient of at least p is a proper factor of
-- m.
fn factorOf(erased m : Nat(), erased p : Nat(), erased q : Nat(),
    erased i : Nat(), dm : DivMod(m, p, q, Zero()), ge : Plus(p, i, q),
    pr : Prime(p))
    -> (erased f : Factor(p, m)) {
  let PrimeIntro(_, nd) = pr;
  let (erased j, erased e) = ndTwo(_, _, nd);
  match erased e : _ {
    Refl(_, _) => {
      let (erased t) = exactTimes(_, _, _, dm);
      let (erased x, erased y, erased tx, erased ty, erased s) =
        timesSplit(_, _, _, _, _, ge, t);
      let (erased w, erased lt) = ltSquare(_, _, tx);
      let (erased wy, erased q1, erased q2) = plusAssoc(_, _, _, _, _, lt, s);
      FactorIntro(_, _, _, _, _, t,
          PlusSucc(_, _, _, PlusSucc(_, _, _, PlusZero(_))), q2)
    };
  }
}

-- A number with a proper factor is not prime.
fn factorNotPrime(erased d : Nat(), erased n : Nat(), f : Factor(d, n),
    pr : Prime(n))
    -> (erased r : False()) {
  let FactorIntro(_, _, _, _, _, t, lo, hi) = f;
  let PlusSucc(_, _, _, lo1) = lo;
  let PlusSucc(_, _, _, _) = lo1;
  let PrimeIntro(_, nd) = pr;
  noFactor(_, _, _, _, _, nd, hi, t)
}

-- If i does not divide m, it does not divide any j that divides m.
fn notDivDivisor(erased i : Nat(), erased m : Nat(), erased q : Nat(),
    erased j : Nat(), nd : NotDivides(i, m), t : Times(q, j, m))
    -> (erased r : NotDivides(i, j)) {
  let NotDiv(_, _, _, _, dm) = nd;
  let DivModIntro(_, _, _, _, _, _, _, _, l) = dm;
  let PlusSucc(_, _, _, _) = l;
  let (erased q2, erased r2, erased dm2) = divmod(j, i, NonZeroSucc(_));
  match erased r2 : _ {
    Zero() => {
      let (erased c, erased u) =
        timesAssoc(_, _, _, _, _, t, exactTimes(_, _, _, dm2));
      match erased divUniqueFalse(_, _, _, _, _, dm, u) : _ {}
    };
    Succ(_) => NotDiv(_, _, _, _, dm2);
  }
}

-- The same for everything NoDivBelow covers: if nothing below i divides m,
-- nothing below i divides a divisor j of m.
fn noDivDivisor(erased m : Nat(), erased i : Nat(), erased q : Nat(),
    erased j : Nat(), subterm nd : NoDivBelow(m, i), t : Times(q, j, m))
    -> (erased r : NoDivBelow(j, i)) {
  match nd : _ {
    NoDivTwo(_) => NoDivTwo(_);
    NoDivStep(_, _, rest, nd1) => NoDivStep(_, _,
        noDivDivisor(_, _, _, _, subterm rest, t),
        notDivDivisor(_, _, _, _, nd1, t));
  }
}

-- Everything on the list is prime.
fn listedPrime(erased p : Nat(), erased l : NatList(), erased k : Nat(),
    m : Mem(p, l), subterm ex : PrimesBelow(l, k))
    -> (erased r : Prime(p)) {
  match ex : _ {
    PrimesTwo() => match m : _ {};
    PrimesAdd(_, _, rest, pk) => match m : _ {
      Here(_, _) => pk;
      There(_, _, _, m1) => listedPrime(_, _, _, m1, subterm rest);
    };
    PrimesSkip(_, _, _, rest, _) => listedPrime(_, _, _, m, subterm rest);
  }
}

-- Every prime below k is on the list.
fn primeListed(erased p : Nat(), erased w : Nat(), erased l : NatList(),
    erased k : Nat(), pr : Prime(p), lt : Plus(Succ(p), w, k),
    subterm ex : PrimesBelow(l, k))
    -> (erased m : Mem(p, l)) {
  match ex : _ {
    PrimesTwo() => {
      let PrimeIntro(_, nd) = pr;
      let (erased j, erased e) = ndTwo(_, _, nd);
      match erased e : _ {
        Refl(_, _) => {
          let PlusSucc(_, _, _, l1) = lt;
          let PlusSucc(_, _, _, l2) = l1;
          match l2 : _ {}
        };
      }
    };
    PrimesAdd(_, _, rest, _) => match erased plusComm(_, _, _, lt) : _ {
      PlusZero(_) => Here(_, _);
      PlusSucc(_, _, _, l1) => There(_, _, _,
          primeListed(_, _, _, _, pr, plusComm(_, _, _, l1), subterm rest));
    };
    PrimesSkip(_, _, _, rest, f) => match erased plusComm(_, _, _, lt) : _ {
      PlusZero(_) => match erased factorNotPrime(_, _, f, pr) : _ {};
      PlusSucc(_, _, _, l1) =>
        primeListed(_, _, _, _, pr, plusComm(_, _, _, l1), subterm rest);
    };
  }
}

-- Dropping the newest prime p from the list leaves the list of primes below p.
fn tailBelow(erased p : Nat(), erased l : NatList(), erased k : Nat(),
    subterm ex : PrimesBelow(NCons(p, l), k))
    -> (erased w : Nat(), erased e : PrimesBelow(l, p),
        erased lt : Plus(Succ(p), w, k)) {
  match ex : _ {
    PrimesAdd(_, _, rest, _) => (Zero(), rest, plusZeroRight(Succ(p)));
    PrimesSkip(_, _, _, rest, _) => {
      let (erased w, erased e, erased lt) = tailBelow(_, _, _, subterm rest);
      (Succ(w), e, plusSucc(_, _, _, lt))
    };
  }
}

-- A j on the list with j * j <= m, once checked, cannot divide m.
fn checkedFalse(erased j : Nat(), erased l : NatList(), erased m : Nat(),
    erased q : Nat(), erased x : Nat(), erased y : Nat(),
    subterm mem : Mem(j, l), c : Checked(l, m), t : Times(q, j, m),
    tx : Times(j, j, x), s : Plus(x, y, m))
    -> (erased f : False()) {
  match mem : _ {
    Here(_, _) => {
      let CheckedCons(_, _, _, _, o) = c;
      match o : _ {
        Inl(_, _, nd) => {
          let NotDiv(_, _, _, _, dm) = nd;
          divUniqueFalse(_, _, _, _, _, dm, t)
        };
        Inr(_, _, u) =>
          notBelowSquare(_, _, _, _, _, _, u, plusZeroRight(j), tx, s);
      }
    };
    There(_, _, _, m1) => {
      let CheckedCons(_, _, _, rest, _) = c;
      checkedFalse(_, _, _, _, _, _, subterm m1, rest, t, tx, s)
    };
  }
}

-- The heart of the proof. Suppose nothing below j divides m, and yet j, smaller
-- than m, does: q * j = m. If q < j, then q is itself a divisor below j.
-- Otherwise j * j <= m, and j is prime, because a divisor of j would divide m.
-- So j is on the list and was checked. Every case is impossible.
fn divisorFalse(erased m : Nat(), erased j : Nat(), erased i : Nat(),
    erased q : Nat(), erased l : NatList(), erased k : Nat(),
    nd : NoDivBelow(m, j), cn : Plus(Succ(j), i, m), t : Times(q, j, m),
    ex : PrimesBelow(l, k), c : Checked(l, m), u : BelowSquare(m, k))
    -> (erased f : False()) {
  match erased compare(q, j) : _ {
    CmpLt(_, _, _, lt) => match erased q : _ {
      Zero() => {
        let TimesZero(_) = t;
        match cn : _ {}
      };
      Succ(q1) => match erased q1 : _ {
        Zero() => {
          let TimesSucc(_, _, _, _, t1, p1) = t;
          let TimesZero(_) = t1;
          let PlusZero(_) = p1;
          noGrow(_, _, plusMove(_, _, _, cn))
        };
        Succ(_) => noFactor(_, _, _, _, _, nd, lt, timesComm(_, _, _, t));
      };
    };
    CmpGe(_, _, _, ge) => {
      let (erased x, erased y, erased tx, erased ty, erased s) =
        timesSplit(_, _, _, _, _, ge, t);
      match erased compare(j, k) : _ {
        CmpGe(_, _, _, kj) => notBelowSquare(_, _, _, _, _, _, u, kj, tx, s);
        CmpLt(_, _, _, jk) => {
          let (erased pr) = PrimeIntro(_, noDivDivisor(_, _, _, _, nd, t));
          checkedFalse(_, _, _, _, _, _, primeListed(_, _, _, _, pr, jk, ex), c,
              t, tx, s)
        };
      }
    };
  }
}

-- Grows "nothing below j divides m" one j at a time until j reaches m, which is
-- Prime(m). divisorFalse rules out each new j. The loop is unary and erased: it
-- is the proof, and is not meant to run.
fn buildPrime(subterm i : Nat(), erased m : Nat(), erased j : Nat(),
    erased l : NatList(), erased k : Nat(), nd : NoDivBelow(m, j),
    p : Plus(j, i, m), ex : PrimesBelow(l, k), c : Checked(l, m),
    u : BelowSquare(m, k))
    -> (erased r : NoDivBelow(m, m)) {
  match i : _ {
    Zero() => match erased plusFunc(_, _, _, _, plusZeroRight(j), p) : _ {
      Refl(_, _) => nd;
    };
    Succ(i1) => {
      let (erased cn) = plusMoveBack(_, _, _, p);
      let (erased j2, erased e) = ndTwo(_, _, nd);
      match erased e : _ {
        Refl(_, _) => {
          let (erased q, erased r, erased dm) = divmod(m, j, NonZeroSucc(_));
          let (erased nd1) = match erased r : (erased nd1 : NotDivides(j, m)) {
            Zero() => match erased divisorFalse(_, _, _, _, _, _, nd, cn,
                exactTimes(_, _, _, dm), ex, c, u) : _ {};
            Succ(_) => NotDiv(_, _, _, _, dm);
          };
          buildPrime(subterm i1, _, _, _, _, NoDivStep(_, _, nd, nd1), cn, ex,
              c, u)
        };
      }
    };
  }
}

-- ---- Binary arithmetic ----

-- A Pos never stands for zero.
fn posPos(erased x : Pos(), erased k : Nat(), subterm r : PosRep(x, k))
    -> (erased z : NonZero(k)) {
  match r : _ {
    RepOne() => NonZeroSucc(_);
    RepP0(_, _, _, r1, s) => {
      let erased NonZeroSucc(_) = posPos(_, _, subterm r1);
      let PlusSucc(_, _, _, _) = s;
      NonZeroSucc(_)
    };
    RepP1(_, _, _, _, _) => NonZeroSucc(_);
  }
}

-- Twice a positive number is at least 2.
fn atLeastTwo(erased b : Pos(), erased nb : Nat(), erased d : Nat(),
    rb : PosRep(b, nb), sb : Plus(nb, nb, d))
    -> (erased w : Nat(), erased p : Plus(Succ(Succ(Zero())), w, d)) {
  let erased NonZeroSucc(_) = posPos(_, _, rb);
  ltDouble(_, _, _, _, _, PlusSucc(_, _, _, PlusZero(_)), PlusZero(_), sb)
}

-- Every binary number stands for some unary number. The result is erased: it is
-- known to exist without being computed.
fn toNatPos(subterm x : Pos()) -> (erased n : Nat(), erased r : PosRep(x, n)) {
  match x : _ {
    One() => (Succ(Zero()), RepOne());
    P0(a) => {
      let (erased k, erased r) = toNatPos(subterm a);
      let (erased d, erased s) = plus(k, k);
      (d, RepP0(_, _, _, r, s))
    };
    P1(a) => {
      let (erased k, erased r) = toNatPos(subterm a);
      let (erased d, erased s) = plus(k, k);
      (Succ(d), RepP1(_, _, _, r, s))
    };
  }
}

-- The same for Bin.
fn toNat(b : Bin()) -> (erased n : Nat(), erased r : Rep(b, n)) {
  match b : _ {
    BZ() => (Zero(), RepZ());
    BP(p) => {
      let (erased n, erased r) = toNatPos(p);
      (n, RepP(_, _, r))
    };
  }
}

-- Adds one in binary, with evidence that the result stands for m + 1. In the
-- last case, 2a + 1 plus one carries: the digit becomes 0 and one is added to
-- the digits above it.
fn succPos(erased m : Nat(), subterm x : Pos(), erased px : PosRep(x, m))
    -> (z : Pos(), erased pz : PosRep(z, Succ(m))) {
  match x : _ {
    One() => {
      let erased RepOne() = px;
      (P0(One()), RepP0(_, _, _, RepOne(), PlusSucc(_, _, _, PlusZero(_))))
    };
    P0(a) => {
      let erased RepP0(_, _, _, ra, sa) = px;
      (P1(a), RepP1(_, _, _, ra, sa))
    };
    P1(a) => {
      let erased RepP1(_, _, _, ra, sa) = px;
      let (z, erased pz) = succPos(_, subterm a, ra);
      (P0(z), RepP0(_, _, _, pz, succBoth(_, _, _, sa)))
    };
  }
}

-- The same for Bin.
fn inc(erased n : Nat(), b : Bin(), erased pb : Rep(b, n))
    -> (c : Bin(), erased pc : Rep(c, Succ(n))) {
  match b : _ {
    BZ() => {
      let erased RepZ() = pb;
      (BP(One()), RepP(_, _, RepOne()))
    };
    BP(p) => {
      let erased RepP(_, _, r) = pb;
      let (q, erased pq) = succPos(_, p, r);
      (BP(q), RepP(_, _, pq))
    };
  }
}

-- Doubles a binary number by writing a 0 after it. Zero stays zero.
fn twice(erased k : Nat(), erased d : Nat(), z : Bin(), erased r : Rep(z, k),
    erased s : Plus(k, k, d))
    -> (w : Bin(), erased rw : Rep(w, d)) {
  match z : _ {
    BZ() => {
      let erased RepZ() = r;
      let erased PlusZero(_) = s;
      (BZ(), RepZ())
    };
    BP(p) => {
      let erased RepP(_, _, rp) = r;
      (BP(P0(p)), RepP(_, _, RepP0(_, _, _, rp, s)))
    };
  }
}

-- Doubles and adds one, by writing a 1 after it.
fn twice1(erased k : Nat(), erased d : Nat(), z : Bin(), erased r : Rep(z, k),
    erased s : Plus(k, k, d))
    -> (w : Bin(), erased rw : Rep(w, Succ(d))) {
  match z : _ {
    BZ() => {
      let erased RepZ() = r;
      let erased PlusZero(_) = s;
      (BP(One()), RepP(_, _, RepOne()))
    };
    BP(p) => {
      let erased RepP(_, _, rp) = r;
      (BP(P1(p)), RepP(_, _, RepP1(_, _, _, rp, s)))
    };
  }
}

-- Subtraction goes digit by digit. Each of these four takes the answer for a -
-- b and gives the answer once one more digit is written after each number; the
-- name gives the two digits. This one: 2a - 2b is twice a - b.
fn lift00(erased a : Nat(), erased b : Nat(), erased da : Nat(),
    erased db : Nat(), x : Diff(a, b), erased sa : Plus(a, a, da),
    erased sb : Plus(b, b, db))
    -> (y : Diff(da, db)) {
  match x : _ {
    Above(z, _, _, k, rz, p) => {
      let (erased dk, erased sk) = plus(k, k);
      let (w, erased rw) = twice(_, _, z, rz, sk);
      Above(w, _, _, dk, rw, dsum(_, _, _, _, _, _, p, sb, sk, sa))
    };
    Below(_, _, _, p) => {
      let (erased w, erased q) = ltDouble(_, _, _, _, _, p, sa, sb);
      Below(_, _, Succ(w), plusMove(_, _, _, q))
    };
  }
}

-- (2a + 1) - (2b + 1) is the same as 2a - 2b.
fn lift11(erased a : Nat(), erased b : Nat(), erased da : Nat(),
    erased db : Nat(), x : Diff(a, b), erased sa : Plus(a, a, da),
    erased sb : Plus(b, b, db))
    -> (y : Diff(Succ(da), Succ(db))) {
  match lift00(_, _, _, _, x, sa, sb) : _ {
    Above(z, _, _, k, rz, p) => Above(z, _, _, k, rz, PlusSucc(_, _, _, p));
    Below(_, _, k, p) => Below(_, _, k, PlusSucc(_, _, _, p));
  }
}

-- (2a + 1) - 2b is twice a - b, plus one.
fn lift10(erased a : Nat(), erased b : Nat(), erased da : Nat(),
    erased db : Nat(), x : Diff(a, b), erased sa : Plus(a, a, da),
    erased sb : Plus(b, b, db))
    -> (y : Diff(Succ(da), db)) {
  match x : _ {
    Above(z, _, _, k, rz, p) => {
      let (erased dk, erased sk) = plus(k, k);
      let (w, erased rw) = twice1(_, _, z, rz, sk);
      Above(w, _, _, Succ(dk), rw,
          plusSucc(_, _, _, dsum(_, _, _, _, _, _, p, sb, sk, sa)))
    };
    Below(_, _, _, p) => {
      let (erased w, erased q) = ltDouble(_, _, _, _, _, p, sa, sb);
      Below(_, _, w, q)
    };
  }
}

-- 2a - (2b + 1) has to borrow. It is worked out from a - (b + 1), which is why
-- the parameter x is about Succ(b).
fn lift01(erased a : Nat(), erased b : Nat(), erased da : Nat(),
    erased db : Nat(), x : Diff(a, Succ(b)), erased sa : Plus(a, a, da),
    erased sb : Plus(b, b, db))
    -> (y : Diff(da, Succ(db))) {
  match x : _ {
    Above(z, _, _, k, rz, p) => {
      let (erased dk, erased sk) = plus(k, k);
      let (w, erased rw) = twice1(_, _, z, rz, sk);
      Above(w, _, _, Succ(dk), rw,
          plusMove(_, _, _,
              dsum(_, _, _, _, _, _, p, succBoth(_, _, _, sb), sk, sa)))
    };
    Below(_, _, _, p) => {
      let (erased w, erased q) =
        ltDouble(_, _, _, _, _, p, sa, succBoth(_, _, _, sb));
      let erased PlusSucc(_, _, _, q1) = q;
      Below(_, _, w, q1)
    };
  }
}

-- Binary subtraction m - n for a positive m: the difference, or the fact that
-- m < n.
fn sub(erased m : Nat(), erased n : Nat(), subterm x : Pos(), y : Bin(),
    erased px : PosRep(x, m), erased py : Rep(y, n))
    -> (r : Diff(m, n)) {
  match x : _ {
    One() => {
      let erased RepOne() = px;
      match y : _ {
        BZ() => {
          let erased RepZ() = py;
          Above(BP(One()), _, _, Succ(Zero()), RepP(_, _, RepOne()),
              PlusZero(_))
        };
        BP(q) => {
          let erased RepP(_, _, rq) = py;
          match q : _ {
            One() => {
              let erased RepOne() = rq;
              Above(BZ(), _, _, Zero(), RepZ(), plusZeroRight(Succ(Zero())))
            };
            P0(b) => {
              let erased RepP0(_, _, _, rb, sb) = rq;
              let (erased w, erased p) = atLeastTwo(_, _, _, rb, sb);
              Below(_, _, w, p)
            };
            P1(b) => {
              let erased RepP1(_, _, _, rb, sb) = rq;
              let (erased w, erased p) = atLeastTwo(_, _, _, rb, sb);
              Below(_, _, Succ(w), plusSucc(_, _, _, p))
            };
          }
        };
      }
    };
    P0(a) => {
      let erased RepP0(_, _, _, ra, sa) = px;
      match y : _ {
        BZ() => {
          let erased RepZ() = py;
          Above(BP(x), _, _, m, RepP(_, _, px), PlusZero(_))
        };
        BP(q) => {
          let erased RepP(_, _, rq) = py;
          match q : _ {
            One() => {
              let erased RepOne() = rq;
              lift01(_, _, _, _,
                  sub(_, _, subterm a, BP(One()), ra, RepP(_, _, RepOne())), sa,
                  PlusZero(_))
            };
            P0(b) => {
              let erased RepP0(_, _, _, rb, sb) = rq;
              lift00(_, _, _, _,
                  sub(_, _, subterm a, BP(b), ra, RepP(_, _, rb)), sa, sb)
            };
            P1(b) => {
              let erased RepP1(_, _, _, rb, sb) = rq;
              let (c, erased rc) = inc(_, BP(b), RepP(_, _, rb));
              lift01(_, _, _, _, sub(_, _, subterm a, c, ra, rc), sa, sb)
            };
          }
        };
      }
    };
    P1(a) => {
      let erased RepP1(_, _, _, ra, sa) = px;
      match y : _ {
        BZ() => {
          let erased RepZ() = py;
          Above(BP(x), _, _, m, RepP(_, _, px), PlusZero(_))
        };
        BP(q) => {
          let erased RepP(_, _, rq) = py;
          match q : _ {
            One() => {
              let erased RepOne() = rq;
              lift11(_, _, _, _, sub(_, _, subterm a, BZ(), ra, RepZ()), sa,
                  PlusZero(_))
            };
            P0(b) => {
              let erased RepP0(_, _, _, rb, sb) = rq;
              lift10(_, _, _, _,
                  sub(_, _, subterm a, BP(b), ra, RepP(_, _, rb)), sa, sb)
            };
            P1(b) => {
              let erased RepP1(_, _, _, rb, sb) = rq;
              lift11(_, _, _, _,
                  sub(_, _, subterm a, BP(b), ra, RepP(_, _, rb)), sa, sb)
            };
          }
        };
      }
    };
  }
}

-- The same when m can be zero.
fn subBin(erased m : Nat(), erased n : Nat(), x : Bin(), y : Bin(),
    erased px : Rep(x, m), erased py : Rep(y, n))
    -> (r : Diff(m, n)) {
  match x : _ {
    BZ() => {
      let erased RepZ() = px;
      match y : _ {
        BZ() => {
          let erased RepZ() = py;
          Above(BZ(), _, _, Zero(), RepZ(), PlusZero(_))
        };
        BP(q) => {
          let erased RepP(_, _, rq) = py;
          let erased NonZeroSucc(n1) = posPos(_, _, rq);
          Below(_, _, n1, PlusSucc(_, _, _, PlusZero(_)))
        };
      }
    };
    BP(p) => {
      let erased RepP(_, _, rp) = px;
      sub(_, _, p, y, rp, py)
    };
  }
}

-- If r2 = d + k and r2 < 2d then k < d.
fn halfBound(erased d : Nat(), erased k : Nat(), erased r2 : Nat(),
    erased w : Nat(), erased dd : Nat(), p : Plus(d, k, r2),
    l : Plus(Succ(r2), w, dd), sd : Plus(d, d, dd))
    -> (erased q : Plus(Succ(k), w, d)) {
  let (erased bc, erased q1, erased q2) =
    plusAssoc(_, _, _, _, _, plusSucc(_, _, _, p), l);
  match erased plusCancel(_, _, _, _, q2, sd) : _ {
    Refl(_, _) => q1;
  }
}

-- One step of long division. It is given a quotient q and a remainder r that
-- may be too big, though below 2d. If d can be subtracted from r, it does so
-- and adds one to q. The result is a proper division: remainder below d.
fn divStep(erased m : Nat(), erased d : Nat(), erased dd : Nat(),
    erased nq : Nat(), erased nr : Nat(), erased t : Nat(), erased w : Nat(),
    q : Bin(), r : Bin(), y : Bin(), erased rq : Rep(q, nq),
    erased rr : Rep(r, nr), erased ry : Rep(y, d), erased tq : Times(nq, d, t),
    erased s : Plus(t, nr, m), erased l : Plus(Succ(nr), w, dd),
    erased sd : Plus(d, d, dd))
    -> (q1 : Bin(), r1 : Bin(), erased nq1 : Nat(), erased nr1 : Nat(),
        erased rq1 : Rep(q1, nq1), erased rr1 : Rep(r1, nr1),
        erased dm : DivMod(m, d, nq1, nr1)) {
  match subBin(_, _, r, y, rr, ry) : _ {
    Above(z, _, _, k, rz, p) => {
      let (q2, erased rq2) = inc(_, q, rq);
      let (erased u, erased s1, erased s2) = plusAssocRev(_, _, _, _, _, p, s);
      (q2, z, Succ(nq), k, rq2, rz,
          DivModIntro(_, _, _, _, u, _, TimesSucc(_, _, _, _, tq, s1), s2,
              halfBound(_, _, _, _, _, p, l, sd)))
    };
    Below(_, _, k, p) =>
      (q, r, nq, nr, rq, rr, DivModIntro(_, _, _, _, t, k, tq, s, p));
  }
}

-- Binary long division of x by y, highest digit first: divide the digits above
-- the lowest one, double the quotient and remainder, bring in the lowest digit,
-- and repair the remainder with divStep. It returns q and r with evidence that
-- they are the division DivMod describes.
fn divPos(erased m : Nat(), erased d : Nat(), subterm x : Pos(), y : Bin(),
    erased px : PosRep(x, m), erased py : Rep(y, d), erased z : NonZero(d))
    -> (q : Bin(), r : Bin(), erased nq : Nat(), erased nr : Nat(),
        erased rq : Rep(q, nq), erased rr : Rep(r, nr),
        erased dm : DivMod(m, d, nq, nr)) {
  let (erased dd, erased sd) = plus(d, d);
  match x : _ {
    One() => {
      let erased RepOne() = px;
      let erased NonZeroSucc(_) = z;
      let (erased w, erased l) = ltDouble(_, _, _, _, _,
          PlusSucc(_, _, _, PlusZero(_)), PlusZero(_), sd);
      divStep(_, _, _, _, _, _, _, BZ(), BP(One()), y, RepZ(),
          RepP(_, _, RepOne()), py, TimesZero(_), PlusZero(_), l, sd)
    };
    P0(a) => {
      let erased RepP0(_, _, _, ra, sa) = px;
      let (q, r, erased nq, erased nr, erased rq, erased rr, erased dm) =
        divPos(_, _, subterm a, y, ra, py, z);
      let erased DivModIntro(_, _, _, _, t, _, tq, s, l) = dm;
      let (erased nq2, erased sq) = plus(nq, nq);
      let (erased nr2, erased sr) = plus(nr, nr);
      let (q2, erased rq2) = twice(_, _, q, rq, sq);
      let (r2, erased rr2) = twice(_, _, r, rr, sr);
      let (erased t2, erased st, erased tq2) = timesDouble(_, _, _, _, sq, tq);
      let (erased w, erased l2) = ltDouble(_, _, _, _, _, l, sr, sd);
      divStep(_, _, _, _, _, _, _, q2, r2, y, rq2, rr2, py, tq2,
          dsum(_, _, _, _, _, _, s, st, sr, sa), plusMove(_, _, _, l2), sd)
    };
    P1(a) => {
      let erased RepP1(_, _, _, ra, sa) = px;
      let (q, r, erased nq, erased nr, erased rq, erased rr, erased dm) =
        divPos(_, _, subterm a, y, ra, py, z);
      let erased DivModIntro(_, _, _, _, t, _, tq, s, l) = dm;
      let (erased nq2, erased sq) = plus(nq, nq);
      let (erased nr2, erased sr) = plus(nr, nr);
      let (q2, erased rq2) = twice(_, _, q, rq, sq);
      let (r2, erased rr2) = twice1(_, _, r, rr, sr);
      let (erased t2, erased st, erased tq2) = timesDouble(_, _, _, _, sq, tq);
      let (erased w, erased l2) = ltDouble(_, _, _, _, _, l, sr, sd);
      divStep(_, _, _, _, _, _, _, q2, r2, y, rq2, rr2, py, tq2,
          plusSucc(_, _, _, dsum(_, _, _, _, _, _, s, st, sr, sa)), l2, sd)
    };
  }
}

-- ---- The decision procedure ----

-- Tries the listed primes on x, smallest first. The list is kept largest first,
-- so the recursive call comes before the test of p. For p: if x divided by p is
-- less than p, stop, since p * p > x. If the remainder is zero, p is a factor.
-- Otherwise p is checked and the next prime gets its turn.
fn trial(x : Pos(), erased m : Nat(), erased px : PosRep(x, m),
    erased l : NatList(), subterm ps : PList(l), erased k : Nat(),
    erased ex : PrimesBelow(l, k))
    -> (o : Trial(l, m, k)) {
  match ps : _ {
    PNil() => Pass(_, _, _, CheckedNil(_));
    PCons(p, _, rp, _, rest) => {
      let (erased w, erased ex1, erased lt) = tailBelow(_, _, _, ex);
      match trial(x, _, px, _, subterm rest, _, ex1) : _ {
        Found(_, _, _, d, _, rd, f) => Found(_, _, _, d, _, rd, f);
        Stop(_, _, _, c, u) => Stop(_, _, _,
            CheckedCons(_, _, _, c, Inr(_, _, u)),
            belowSquareUp(_, _, _, _, u, lt));
        Pass(_, _, _, c) => {
          let erased NonZeroSucc(_) = posPos(_, _, rp);
          let (q, r, erased nq, erased nr, erased rq, erased rr, erased dm) =
            divPos(_, _, x, BP(p), px, RepP(_, _, rp), NonZeroSucc(_));
          match subBin(_, _, q, BP(p), rq, RepP(_, _, rp)) : _ {
            Below(_, _, _, lq) => {
              let (erased u) = divBig(_, _, _, _, _, dm, lq);
              Stop(_, _, _, CheckedCons(_, _, _, c, Inr(_, _, u)),
                  belowSquareUp(_, _, _, _, u, lt))
            };
            Above(_, _, _, _, _, ge) => match r : _ {
              BZ() => {
                let erased RepZ() = rr;
                Found(_, _, _, BP(p), _, RepP(_, _, rp),
                    factorOf(_, _, _, _, dm, ge,
                        listedPrime(_, _, _, Here(_, _), ex)))
              };
              BP(r1) => {
                let erased RepP(_, _, rr1) = rr;
                let erased NonZeroSucc(_) = posPos(_, _, rr1);
                Pass(_, _, _,
                    CheckedCons(_, _, _, c, Inl(_, _, NotDiv(_, _, _, _, dm))))
              };
            };
          }
        };
      }
    };
  }
}

-- Turns the result of trial into a Verdict. When no listed prime divides m,
-- buildPrime supplies the proof that m is prime. It needs u, evidence that the
-- list reaches the square root of m.
fn test(x : Pos(), erased m : Nat(), erased px : PosRep(x, m),
    erased l : NatList(), ps : PList(l), erased k : Nat(), erased a : Nat(),
    erased ex : PrimesBelow(l, k), erased u : BelowSquare(m, k),
    erased two : Plus(Succ(Succ(Zero())), a, m))
    -> (v : Verdict(m)) {
  match trial(x, _, px, _, ps, _, ex) : _ {
    Found(_, _, _, d, _, rd, f) => Composite(_, d, _, rd, f);
    Pass(_, _, _, c) => IsPrime(_,
        PrimeIntro(_, buildPrime(a, _, _, _, _, NoDivTwo(_), two, ex, c, u)));
    Stop(_, _, _, c, _) => IsPrime(_,
        PrimeIntro(_, buildPrime(a, _, _, _, _, NoDivTwo(_), two, ex, c, u)));
  }
}

-- Takes the list from "primes below k" to "primes below k + 1" by testing k,
-- here written Succ(Succ(a)). The BelowTwo case cannot happen, since k is at
-- least 2.
fn grow(k : Pos(), erased a : Nat(), erased kk : Nat(),
    erased pk : PosRep(k, Succ(Succ(a))), erased l : NatList(), ps : PList(l),
    erased ex : PrimesBelow(l, Succ(Succ(a))),
    erased t : Times(Succ(Succ(a)), Succ(Succ(a)), kk))
    -> (erased l2 : NatList(), ps2 : PList(l2),
        erased ex2 : PrimesBelow(l2, Succ(Succ(Succ(a))))) {
  let (erased w, erased lt) = ltSquare(_, _, t);
  match test(k, _, pk, _, ps, _, _, ex, BelowSquareIntro(_, _, _, _, t, lt),
      PlusSucc(_, _, _, PlusSucc(_, _, _, PlusZero(_)))) : _ {
    IsPrime(_, pr) => (NCons(Succ(Succ(a)), l), PCons(k, _, pk, _, ps),
        PrimesAdd(_, _, ex, pr));
    Composite(_, _, _, _, f) => (l, ps, PrimesSkip(_, _, _, ex, f));
    BelowTwo(_, _, p) => {
      let erased PlusSucc(_, _, _, p1) = p;
      let erased PlusSucc(_, _, _, p2) = p1;
      match erased p2 : _ {}
    };
  }
}

-- The main loop. j counts up from 1, and g is the gap between n and j * j, in
-- binary. Each round tries to take 2j + 1 off the gap. If it cannot,
-- (j + 1) * (j + 1) > n: the list reaches far enough, and n itself is tested.
-- If it can, j + 1 is tested, listed if prime, and the loop goes round again.
--
-- Nothing that exists at run time gets structurally smaller here, so the
-- `subterm` parameter is b, an erased unary bound on the gap. It shrinks every
-- round, which is enough to show that the loop ends.
fn ascend(subterm erased b : Nat(), x : Pos(), j : Pos(), g : Bin(),
    erased l : NatList(), ps : PList(l), erased n : Nat(), erased nj : Nat(),
    erased jj : Nat(), erased ng : Nat(), erased e : Nat(), erased a : Nat(),
    erased px : PosRep(x, n), erased pj : PosRep(j, nj), erased rg : Rep(g, ng),
    erased ex : PrimesBelow(l, Succ(nj)), erased t : Times(nj, nj, jj),
    erased s : Plus(jj, ng, n), erased gb : Plus(ng, e, b),
    erased two : Plus(Succ(Succ(Zero())), a, n))
    -> (v : Verdict(n)) {
  let (erased d, erased dd) = plus(nj, nj);
  match subBin(_, _, g, BP(P1(j)), rg, RepP(_, _, RepP1(_, _, _, pj, dd))) : _ {
    Below(_, _, _, lt) => {
      let (erased kk, erased s1) = plus(jj, Succ(d));
      test(x, _, px, _, ps, _, _, ex,
          BelowSquareIntro(_, _, _, _, squareStep(_, _, _, _, t, dd, s1),
              succLess(_, _, _, _, _, _, s, lt, s1)),
          two)
    };
    Above(g1, _, _, _, rg1, p) => {
      let (erased kk, erased s1, erased s2) = plusAssocRev(_, _, _, _, _, p, s);
      let (erased tk) = squareStep(_, _, _, _, t, dd, s1);
      let erased PlusSucc(_, _, _, p1) = p;
      let erased PlusSucc(_, _, b1, gb1) = gb;
      let (erased de, erased q1, erased q2) =
        plusAssoc(_, _, _, _, _, plusComm(_, _, _, p1), gb1);
      let erased NonZeroSucc(_) = posPos(_, _, pj);
      let (k, erased pk) = succPos(_, j, pj);
      let (erased l2, ps2, erased ex2) = grow(k, _, _, pk, _, ps, ex, tk);
      ascend(subterm b1, x, k, g1, _, ps2, _, _, _, _, _, _, px, pk, rg1, ex2,
          tk, s2, q2, two)
    };
  }
}

-- The entry point. Below 2 the answer is BelowTwo. Otherwise the loop starts at
-- j = 1 with the gap n - 1 and an empty list.
fn decidePrime(x : Bin(), erased n : Nat(), erased rx : Rep(x, n))
    -> (v : Verdict(n)) {
  match subBin(_, _, x, BP(P0(One())), rx,
      RepP(_, _,
          RepP0(_, _, _, RepOne(), PlusSucc(_, _, _, PlusZero(_))))) : _ {
    Below(_, _, _, p) => BelowTwo(_, _, p);
    Above(g, _, _, a, rg, two) => match x : _ {
      BZ() => {
        let erased RepZ() = rx;
        match erased two : _ {}
      };
      BP(p) => {
        let erased RepP(_, _, rp) = rx;
        let (g1, erased rg1) = inc(_, g, rg);
        ascend(Succ(a), p, One(), g1, _, PNil(), _, _, _, _, _, _, rp, RepOne(),
            rg1, PrimesTwo(), TimesSucc(_, _, _, _, TimesZero(_), PlusZero(_)),
            plusMove(_, _, _, two), plusZeroRight(Succ(a)), two)
      };
    };
  }
}

-- Code at the top level runs as soon as it is checked. This is 4999 in binary,
-- lowest digit first.
let prime = BP(P1(P1(P1(P0(P0(P0(P0(P1(P1(P1(P0(P0(One())))))))))))));
-- Both results of toNat are erased, so the call is not run. It gives the
-- checker a name, nPrime, for "the number prime stands for".
let (erased nPrime, erased rPrime) = toNat(prime);
-- `comptime let` runs decidePrime now, during checking, and requires the answer
-- to be an IsPrime. From here on primeIsPrime has type Prime(nPrime): a proof
-- that 4999 is prime, made by running the program. A plain `let` would be
-- rejected, because without running it the checker cannot tell which Verdict
-- comes back.
comptime let IsPrime(_, primeIsPrime) = decidePrime(prime, nPrime, rPrime);

-- 899, which is 29 * 31. The print shows Composite holding the factor 29,
-- P1(P0(P1(P1(One())))) in binary. Erased fields are not there at run time and
-- print as `_`.
let composite = BP(P1(P1(P0(P0(P0(P0(P0(P1(P1(One()))))))))));
let (erased nComposite, erased rComposite) = toNat(composite);
print decidePrime(composite, nComposite, rComposite);

-- Type safety.
-- The theorem behind the slogan "well-typed programs don't go wrong", proved
-- for a toy language of booleans and numbers. It is the language of chapter 8
-- of Pierce's "Types and Programming Languages".
--
-- The toy language's syntax, its type system and its evaluation rules are each
-- a `data` declaration below. Two facts are proved about them. Preservation: a
-- step of evaluation keeps a term's type. Progress: a well-typed term is
-- finished or can take a step. Together they give the goal, safety: a
-- well-typed term never gets stuck, however many steps it has taken.
--
-- Mind the names. True(), Zero(), Succ(...), Bool() and Nat() in this file are
-- pieces of the toy language, declared below. Pledge has no booleans or numbers
-- of its own.
--
-- If Pledge is new to you:
--   * `data` declares a type and lists every way to build a value of it.
--   * A type can take values as parameters. `HasType(e, t)` below is a separate
--     type for each term e and type t, and it is written so that a value of it
--     can be built only when e has type t. So a value of type `HasType(e, t)`
--     is evidence, a proof, that e has type t. Most types in this file are like
--     that.
--   * `erased` marks what exists only for the checker. Running the program
--     skips it, so here the proofs cost nothing at run time.
--   * The Tutorial link at the top of the page teaches all of this in order.

-- The toy language's programs, as syntax trees. Everything applied is written
-- with parentheses, even with no arguments. Nothing here rules out nonsense:
-- Succ(True()) is a Term too.
data Term() : Type() {
  True() : Term();
  False() : Term();
  If(c : Term(), a : Term(), b : Term()) : Term();
  Zero() : Term();
  Succ(x : Term()) : Term();
  Pred(x : Term()) : Term();
  IsZero(x : Term()) : Term();
}

-- The toy language's two types.
data Ty() : Type() {
  Bool() : Ty();
  Nat() : Ty();
}

-- HasType(e, t) reads "term e has type t". Each constructor is one rule of the
-- type system. TIf, for example: the condition has type Bool and the two
-- branches share a type t, which is then the type of the whole If. No rule fits
-- Succ(True()), so it has no type.
data HasType(e : Term(), t : Ty()) : Type() {
  TTrue() : HasType(True(), Bool());
  TFalse() : HasType(False(), Bool());
  TIf(erased c : Term(), erased a : Term(), erased b : Term(), erased t : Ty(),
      erased dc : HasType(c, Bool()), erased da : HasType(a, t),
      erased db : HasType(b, t)) : HasType(If(c, a, b), t);
  TZero() : HasType(Zero(), Nat());
  TSucc(erased x : Term(), erased dx : HasType(x, Nat()))
    : HasType(Succ(x), Nat());
  TPred(erased x : Term(), erased dx : HasType(x, Nat()))
    : HasType(Pred(x), Nat());
  TIsZero(erased x : Term(), erased dx : HasType(x, Nat()))
    : HasType(IsZero(x), Bool());
}

-- NumVal(e) reads "e is a finished number": Zero(), or Succ of one.
data NumVal(e : Term()) : Type() {
  NVZero() : NumVal(Zero());
  NVSucc(erased x : Term(), erased nv : NumVal(x)) : NumVal(Succ(x));
}

-- Value(e) reads "e is finished: there is nothing left to evaluate".
data Value(e : Term()) : Type() {
  VTrue() : Value(True());
  VFalse() : Value(False());
  VNum(erased e : Term(), nv : NumVal(e)) : Value(e);
}

-- Step(e, e2) reads "one step of evaluation turns e into e2". The rules with no
-- `s` do some work: EIfTrue picks a branch. The rules with an `s` take a step
-- inside a part of the term: EIf works on the condition while it is not yet
-- True() or False().
data Step(e : Term(), e2 : Term()) : Type() {
  EIfTrue(erased a : Term(), erased b : Term()) : Step(If(True(), a, b), a);
  EIfFalse(erased a : Term(), erased b : Term()) : Step(If(False(), a, b), b);
  EIf(erased c : Term(), erased c2 : Term(), erased a : Term(),
      erased b : Term(), erased s : Step(c, c2))
    : Step(If(c, a, b), If(c2, a, b));
  ESucc(erased x : Term(), erased x2 : Term(), erased s : Step(x, x2))
    : Step(Succ(x), Succ(x2));
  EPredZero() : Step(Pred(Zero()), Zero());
  EPredSucc(erased x : Term(), erased nv : NumVal(x)) : Step(Pred(Succ(x)), x);
  EPred(erased x : Term(), erased x2 : Term(), erased s : Step(x, x2))
    : Step(Pred(x), Pred(x2));
  EIsZeroZero() : Step(IsZero(Zero()), True());
  EIsZeroSucc(erased x : Term(), erased nv : NumVal(x))
    : Step(IsZero(Succ(x)), False());
  EIsZero(erased x : Term(), erased x2 : Term(), erased s : Step(x, x2))
    : Step(IsZero(x), IsZero(x2));
}

-- Steps(e, e2) reads "zero or more steps turn e into e2".
data Steps(e : Term(), e2 : Term()) : Type() {
  Stay(erased e : Term()) : Steps(e, e);
  Then(erased e : Term(), erased e2 : Term(), erased e3 : Term(),
      erased s : Step(e, e2), erased ss : Steps(e2, e3)) : Steps(e, e3);
}

-- Progress(e) reads "e is finished, or e can take a step". In Next the term e2
-- is not erased. It is the actual next term, so a function that returns a
-- Progress(e) is also a one-step evaluator.
data Progress(e : Term()) : Type() {
  Done(erased e : Term(), v : Value(e)) : Progress(e);
  Next(erased e : Term(), e2 : Term(), erased s : Step(e, e2)) : Progress(e);
}

-- Preservation: if e steps to e2 and e has type t, then e2 has type t.
--
-- The recursion is on s, the evidence of the step. Evidence is data like any
-- other and can be matched on and recursed over. `subterm` is how a recursive
-- function shows that it ends: each recursive call must pass, for that
-- parameter, a piece of the caller's own argument, here s1 from inside s. The
-- checker demands this of every recursive function; one that might loop forever
-- is rejected.
--
-- `match erased` matches on an erased value. After the colon comes what the
-- match produces, and `_` leaves that to the checker, which knows it from the
-- return type. As an argument, `_` is an erased value the checker can work out
-- for itself.
--
-- There is one branch per Step rule. A `let` with a constructor on the left
-- takes a value apart, and is accepted only when the value can have been built
-- no other way. In the EIfTrue branch e is known to be an If, and TIf is the
-- only typing rule for an If, so d must be a TIf.
fn preservation(erased e : Term(), erased e2 : Term(),
    subterm erased s : Step(e, e2), erased t : Ty(), erased d : HasType(e, t))
    -> (erased d2 : HasType(e2, t)) {
  match erased s : _ {
    EIfTrue(_, _) => { let erased TIf(_, _, _, _, _, da, _) = d; da };
    EIfFalse(_, _) => { let erased TIf(_, _, _, _, _, _, db) = d; db };
    EIf(_, _, _, _, s1) => {
      let erased TIf(_, _, _, _, dc, da, db) = d;
      TIf(_, _, _, _, preservation(_, _, subterm s1, _, dc), da, db)
    };
    ESucc(_, _, s1) => {
      let erased TSucc(_, dx) = d;
      TSucc(_, preservation(_, _, subterm s1, _, dx))
    };
    EPredZero() => { let erased TPred(_, _) = d; TZero() };
    EPredSucc(_, _) => {
      let erased TPred(_, dx) = d;
      let erased TSucc(_, dy) = dx;
      dy
    };
    EPred(_, _, s1) => {
      let erased TPred(_, dx) = d;
      TPred(_, preservation(_, _, subterm s1, _, dx))
    };
    EIsZeroZero() => { let erased TIsZero(_, _) = d; TTrue() };
    EIsZeroSucc(_, _) => { let erased TIsZero(_, _) = d; TFalse() };
    EIsZero(_, _, s1) => {
      let erased TIsZero(_, dx) = d;
      TIsZero(_, preservation(_, _, subterm s1, _, dx))
    };
  }
}

-- A finished term of type Nat is a finished number.
fn canonNat(erased e : Term(), v : Value(e), erased d : HasType(e, Nat()))
    -> (nv : NumVal(e)) {
  match v : _ {
    -- A match with no branches says "this cannot happen", and the checker has
    -- to agree. Here d would be evidence that True() has type Nat. No HasType
    -- rule gives that, so there is no case to write.
    VTrue() => match erased d : _ {};
    VFalse() => match erased d : _ {};
    VNum(_, nv) => nv;
  }
}

-- Progress: a well-typed term is finished or can take a step. When run, this
-- performs one step of evaluation. The typing evidence d is erased; its job is
-- to convince the checker that no case is missing.
fn progress(subterm e : Term(), erased t : Ty(), erased d : HasType(e, t))
    -> (r : Progress(e)) {
  match e : _ {
    True() => Done(_, VTrue());
    False() => Done(_, VFalse());
    Zero() => Done(_, VNum(_, NVZero()));
    If(c, a, b) => {
      let erased TIf(_, _, _, _, dc, _, _) = d;
      match progress(subterm c, _, dc) : _ {
        Done(_, v) => match v : _ {
          VTrue() => Next(_, a, EIfTrue(a, b));
          VFalse() => Next(_, b, EIfFalse(a, b));
          -- The condition of an If cannot be a number, because dc says it has
          -- type Bool. The checker cannot use that until it knows which number.
          -- Once nv is matched, the condition is known to be Zero() or a Succ,
          -- and no HasType rule gives either of those the type Bool.
          VNum(_, nv) => match erased nv : _ {
            NVZero() => match erased dc : _ {};
            NVSucc(_, _) => match erased dc : _ {};
          };
        };
        Next(_, c2, s) => Next(_, If(c2, a, b), EIf(_, _, _, _, s));
      }
    };
    Succ(x) => {
      let erased TSucc(_, dx) = d;
      match progress(subterm x, _, dx) : _ {
        Done(_, v) => Done(_, VNum(_, NVSucc(x, canonNat(_, v, dx))));
        Next(_, x2, s) => Next(_, Succ(x2), ESucc(_, _, s));
      }
    };
    Pred(x) => {
      let erased TPred(_, dx) = d;
      match progress(subterm x, _, dx) : _ {
        Done(_, v) => match canonNat(_, v, dx) : _ {
          NVZero() => Next(_, Zero(), EPredZero());
          -- The match has told the checker that x is a Succ, so this `let` is
          -- accepted.
          NVSucc(_, nv) => { let Succ(y) = x; Next(_, y, EPredSucc(_, nv)) };
        };
        Next(_, x2, s) => Next(_, Pred(x2), EPred(_, _, s));
      }
    };
    IsZero(x) => {
      let erased TIsZero(_, dx) = d;
      match progress(subterm x, _, dx) : _ {
        Done(_, v) => match canonNat(_, v, dx) : _ {
          NVZero() => Next(_, True(), EIsZeroZero());
          NVSucc(_, nv) => Next(_, False(), EIsZeroSucc(_, nv));
        };
        Next(_, x2, s) => Next(_, IsZero(x2), EIsZero(_, _, s));
      }
    };
  }
}

-- Preservation again, over any number of steps.
fn preservationStar(erased e : Term(), erased e2 : Term(),
    subterm erased ss : Steps(e, e2), erased t : Ty(), erased d : HasType(e, t))
    -> (erased d2 : HasType(e2, t)) {
  match erased ss : _ {
    Stay(_) => d;
    Then(_, _, _, s, rest) =>
      preservationStar(_, _, subterm rest, _, preservation(_, _, s, _, d));
  }
}

-- `goal` states the theorem, here as the signature a function must have: if e
-- has type t, and zero or more steps turn e into e2, then e2 is finished or can
-- take a step. So e2 is never stuck. `qed safety` below has the checker confirm
-- that safety is such a function. The page reports whether the goal is proved.
goal fn (erased e : Term(), e2 : Term(), erased t : Ty(),
    erased ss : Steps(e, e2), erased d : HasType(e, t))
    -> (r : Progress(e2));

-- The proof is short: e2 still has type t (preservation), so it is finished or
-- can take a step (progress).
fn safety(erased e : Term(), e2 : Term(), erased t : Ty(),
    erased ss : Steps(e, e2), erased d : HasType(e, t))
    -> (r : Progress(e2)) {
  progress(e2, _, preservationStar(_, _, ss, _, d))
}

qed safety;

-- The rest of the file is an evaluator built from the two proofs. A recursive
-- function has to recurse on a piece of one of its arguments, and "the term
-- after one step" is not a piece of the term. So eval counts down a supply of
-- allowed steps instead.
data Fuel() : Type() {
  Empty() : Fuel();
  More(rest : Fuel()) : Fuel();
}

-- What eval returns: a finished term v with the steps that led to it, or the
-- term it had reached when the fuel ran out. Either way there is evidence that
-- the result still has type t.
data Outcome(e : Term(), t : Ty()) : Type() {
  Halts(erased e : Term(), erased t : Ty(), v : Term(), erased ss : Steps(e, v),
      isv : Value(v), erased dv : HasType(v, t)) : Outcome(e, t);
  OutOfFuel(erased e : Term(), erased t : Ty(), e2 : Term(),
      erased ss : Steps(e, e2), erased d2 : HasType(e2, t)) : Outcome(e, t);
}

-- Each round takes one step with progress, and uses preservation to bring the
-- typing evidence up to date for the next round.
fn eval(subterm fuel : Fuel(), e : Term(), erased t : Ty(),
    erased d : HasType(e, t))
    -> (r : Outcome(e, t)) {
  match fuel : _ {
    Empty() => OutOfFuel(_, _, e, Stay(_), d);
    More(f) => match progress(e, _, d) : _ {
      Done(_, v) => Halts(_, _, e, Stay(_), v, d);
      Next(_, e2, s) =>
        match eval(subterm f, e2, _, preservation(_, _, s, _, d)) : _ {
        Halts(_, _, v, ss, isv, dv) =>
          Halts(_, _, v, Then(_, _, _, s, ss), isv, dv);
        OutOfFuel(_, _, e3, ss, d3) =>
          OutOfFuel(_, _, e3, Then(_, _, _, s, ss), d3);
      };
    };
  }
}

-- Code at the top level runs as soon as it is checked. The term below is "if
-- iszero(pred 1) then 2 else pred 0", and `typing` is the evidence, written out
-- by hand, that it has type Nat.
let one = Succ(Zero());
let term = If(IsZero(Pred(one)), Succ(one), Pred(Zero()));
let erased typing = TIf(_, _, _, _, TIsZero(_, TPred(_, TSucc(_, TZero()))),
    TSucc(_, TSucc(_, TZero())), TPred(_, TZero()));
let fuel = More(More(More(More(More(Empty())))));
-- `print` shows a value next to the statement; erased fields are not there at
-- run time and print as `_`. One step turns "pred 1" into 0. Five units of fuel
-- are enough to reach the value 2. Two are not, and eval reports the term it
-- had reached.
print progress(term, _, typing);
print eval(fuel, term, _, typing);
print eval(More(More(Empty())), term, _, typing);

