let one = Succ(Zero());
let two = Succ(one);
let xs = VCons(Nat(), one, Zero(),
  VCons(Nat(), Zero(), one, VNil(Nat())));
let ys = VCons(Nat(), Zero(), two, VNil(Nat()));
goal fn (A : Type(), m : Nat(), n : Nat(), v : Vec(A, m), w : Vec(A, n))
    -> (r : Nat(), p : Plus(m, n, r), u : Vec(A, r));
fn vappend(A : Type(), m : Nat(), n : Nat(), subterm v : Vec(A, m),
    w : Vec(A, n)) -> (r : Nat(), p : Plus(m, n, r), u : Vec(A, r)) {
  match v : _ {
    VNil(_) => (n, PlusZero(n), w);
    VCons(_, m1, x, rest) => {
      let (r1, p1, u1) = vappend(A, m1, n, subterm rest, w);
      sorry(_)
    };
  }
}
qed vappend;
let (r, p, u) = vappend(Nat(), two, one, xs, ys);
print r;
print u;

data Nat() : Type() {
  Zero() : Nat();
  Succ(pred : Nat()) : Nat();
}

data Vec(A : Type(), n : Nat()) : Type() {
  VNil(A : Type()) : Vec(A, Zero());
  VCons(A : Type(), n : Nat(), head : A, rest : Vec(A, n))
    : Vec(A, Succ(n));
}

data Plus(m : Nat(), n : Nat(), r : Nat()) : Type() {
  PlusZero(n : Nat()) : Plus(Zero(), n, n);
  PlusSucc(m : Nat(), n : Nat(), r : Nat(), p : Plus(m, n, r))
    : Plus(Succ(m), n, Succ(r));
}

fn plus(subterm m : Nat(), n : Nat())
    -> (r : Nat(), p : Plus(m, n, r)) {
  match m : _ {
    Zero() => (n, PlusZero(n));
    Succ(k) => {
      let (r, p) = plus(subterm k, n);
      (Succ(r), PlusSucc(k, n, r, p))
    };
  }
}

fn vhead(A : Type(), n : Nat(), v : Vec(A, Succ(n)))
    -> (x : A) {
  let VCons(_, _, hd, _) = v;
  hd
}
let one = Succ(Zero());
let two = Succ(one);
let xs = VCons(Nat(), one, Zero(),
  VCons(Nat(), Zero(), one, VNil(Nat())));
let ys = VCons(Nat(), Zero(), two, VNil(Nat()));
goal fn (A : Type(), m : Nat(), n : Nat(), v : Vec(A, m), w : Vec(A, n))
    -> (r : Nat(), p : Plus(m, n, r), u : Vec(A, r));
fn vappend(A : Type(), m : Nat(), n : Nat(), subterm v : Vec(A, m),
    w : Vec(A, n)) -> (r : Nat(), p : Plus(m, n, r), u : Vec(A, r)) {
  match v : _ {
    VNil(_) => (n, PlusZero(n), w);
    VCons(_, m1, x, rest) => {
      let (r1, p1, u1) = vappend(A, m1, n, subterm rest, w);
      (Succ(r1), PlusSucc(m1, n, r1, p1), VCons(A, r1, x, u1))
    };
  }
}
qed vappend;
let (r, p, u) = vappend(Nat(), two, one, xs, ys);
print r;
print u;
print vhead(Nat(), two, u);

